window.BELGELER = [{"id": "software-eating-world", "title": "Why Software Is Eating the World", "author": "Marc Andreessen", "date": "2011-08", "cat": "Girişim ve VC", "type": "deneme", "url": "https://a16z.com/why-software-is-eating-the-world/", "pdf": false, "preview": false, "summary": "Yazılım şirketlerinin her sektörü dönüştüreceğini ve geleneksel devlerin yerini alacağını öngören ünlü yazı.", "star": true}, {"id": "do-things-that-dont-scale", "title": "Do Things That Don't Scale", "author": "Paul Graham", "date": "2013-07", "cat": "Girişim ve VC", "type": "deneme", "url": "https://paulgraham.com/ds.html", "pdf": false, "preview": false, "summary": "İlk kullanıcıları elle bulmanın ve onlara olağanüstü ilgi göstermenin neden şart olduğu.", "star": true}, {"id": "aggregation-theory", "title": "Aggregation Theory", "author": "Ben Thompson", "date": "2015-07", "cat": "Girişim ve VC", "type": "deneme", "url": "https://stratechery.com/2015/aggregation-theory/", "pdf": false, "preview": false, "summary": "İnternette güç, ürünü yapandan kullanıcı ilişkisine sahip olan toplayıcıya geçer.", "star": true}, {"id": "1000-true-fans", "title": "1,000 True Fans", "author": "Kevin Kelly", "date": "2008-03", "cat": "Girişim ve VC", "type": "deneme", "url": "https://kk.org/thetechnium/1000-true-fans/", "pdf": false, "preview": false, "summary": "Bir yaratıcının geçinmesi için milyonlarca değil, bin sadık hayran yeter.", "star": true}, {"id": "bitcoin-whitepaper", "title": "Bitcoin: A Peer-to-Peer Electronic Cash System", "author": "Satoshi Nakamoto", "date": "2008-10", "cat": "Teknik makale", "type": "teknik doküman", "url": "https://bitcoin.org/bitcoin.pdf", "pdf": true, "preview": true, "summary": "Aracı olmadan, iş ispatı ile çift harcamayı önleyen eşler arası elektronik nakit sistemi.", "star": true}, {"id": "attention-is-all-you-need", "title": "Attention Is All You Need", "author": "Vaswani et al. (Google)", "date": "2017-06", "cat": "Teknik makale", "type": "makale", "url": "https://arxiv.org/abs/1706.03762", "pdf": false, "preview": false, "summary": "Transformer mimarisini tanıtan makale: tekrarlayan ağlar yerine yalnızca dikkat mekanizması.", "star": true}, {"id": "bitter-lesson", "title": "The Bitter Lesson", "author": "Rich Sutton", "date": "2019-03", "cat": "Yapay zekâ", "type": "deneme", "url": "http://www.incompleteideas.net/IncIdeas/BitterLesson.html", "pdf": false, "preview": false, "summary": "Uzun vadede insan bilgisini kodlamak değil, hesaplamayla ölçeklenen genel yöntemler kazanır.", "star": true}, {"id": "superinvestors-graham-doddsville", "title": "The Superinvestors of Graham-and-Doddsville", "author": "Warren Buffett", "date": "1984", "cat": "Makro ve yatırım", "type": "deneme", "url": "https://www.superinvesting.com/pdf/The-Superinvestors-of-Graham-and-Doddsville-by-Warren-Buffett.pdf", "pdf": true, "preview": true, "summary": "Değer yatırımı yapanların istikrarlı başarısının şans olmadığını gösteren klasik konuşma.", "star": true}, {"id": "meditations-on-moloch", "title": "Meditations on Moloch", "author": "Scott Alexander", "date": "2014-07", "cat": "Dünya görüşü", "type": "deneme", "url": "https://slatestarcodex.com/2014/07/30/meditations-on-moloch/", "pdf": false, "preview": false, "summary": "Rekabetin herkesi, kimsenin istemediği sonuçlara sürüklediği tuzakları anlatan deneme.", "star": true}, {"id": "anatomy-web-search", "title": "The Anatomy of a Large-Scale Hypertextual Web Search Engine", "author": "Sergey Brin, Lawrence Page", "date": "1998-04", "cat": "Teknik makale", "type": "makale", "url": "https://snap.stanford.edu/class/cs224w-readings/Brin98Anatomy.pdf", "pdf": true, "preview": true, "summary": "Google'ın ilk mimarisini ve PageRank fikrini tanıtan makale.", "star": true}, {"id": "information-management-proposal", "title": "Information Management: A Proposal", "author": "Tim Berners-Lee", "date": "1989-03", "cat": "Teknik makale", "type": "makale", "url": "https://w3.org/History/1989/proposal.html", "pdf": false, "preview": false, "summary": "Tim Berners-Lee'nin CERN'e sunduğu ve World Wide Web'i doğuran öneri.", "star": true}, {"id": "mathematical-theory-communication", "title": "A Mathematical Theory of Communication", "author": "Claude Shannon", "date": "1948-07", "cat": "Teknik makale", "type": "makale", "url": "https://people.math.harvard.edu/~ctm/home/text/others/shannon/entropy/entropy.pdf", "pdf": true, "preview": true, "summary": "Bilgiyi ölçülebilir hâle getiren ve bilgi teorisini kuran makale.", "star": true}, {"id": "hamming-you-and-your-research", "title": "You and Your Research", "author": "Richard Hamming", "date": "1986", "cat": "Dünya görüşü", "type": "konuşma", "url": "https://www.cs.virginia.edu/~robins/YouAndYourResearch.pdf", "pdf": true, "preview": true, "summary": "Bell Labs'ın efsane matematikçisi, neden bazı bilim insanlarının büyük işler çıkarıp çoğunun çıkaramadığını anlatıyor: önemli problemleri seç, kapını açık tut, belirsizliğe katlan. Kariyerini ciddiye alan herkes için bir el kitabı.", "star": true}, {"id": "as-we-may-think", "title": "As We May Think", "author": "Vannevar Bush", "date": "1945-07", "cat": "Teknik makale", "type": "deneme", "url": "https://www.w3.org/History/1945/vbush/vbush.shtml", "pdf": false, "preview": false, "summary": "İnsanlığın biriktirdiği bilgiyi çağrışımlarla gezilebilir hale getiren 'memex' makinesini hayal eden yazı. Hiper metin ve web fikrinin 1945'teki tohumu.", "star": true}, {"id": "turing-computing-machinery", "title": "Computing Machinery and Intelligence", "author": "Alan Turing", "date": "1950", "cat": "Yapay zekâ", "type": "makale", "url": "https://courses.cs.umbc.edu/471/papers/turing.pdf", "pdf": true, "preview": false, "summary": "'Makineler düşünebilir mi?' sorusunu ölçülebilir bir oyuna, taklit oyununa çeviriyor ve itirazları tek tek yanıtlıyor. Yapay zekâ tartışmasının hâlâ geçerli başlangıç noktası.", "star": true}, {"id": "no-silver-bullet", "title": "No Silver Bullet: Essence and Accidents of Software Engineering", "author": "Frederick P. Brooks Jr.", "date": "1986", "cat": "Teknik makale", "type": "makale", "url": "https://www.cs.unc.edu/techreports/86-020.pdf", "pdf": true, "preview": true, "summary": "Yazılımdaki asıl zorluğun araçlardan değil, problemin özündeki karmaşıklıktan geldiğini savunuyor; bu yüzden verimliliği on kat artıracak tek bir sihirli çözüm yok. Her yeni 'devrim' vaadini tartmak için iyi bir mercek.", "star": true}, {"id": "pmarca-only-thing-that-matters", "title": "The Only Thing That Matters", "author": "Marc Andreessen", "date": "2007-06", "cat": "Girişim ve VC", "type": "deneme", "url": "https://pmarchive.com/guide_to_startups_part4.html", "pdf": false, "preview": false, "summary": "Bir startup'ın başarısını belirleyen en önemli şeyin ekip ya da ürün değil, pazar olduğunu savunuyor ve 'ürün-pazar uyumu' kavramını yerleştiriyor. Uyumu bulana kadar başka hiçbir şeyin önemi yok.", "star": true}, {"id": "bezos-1997-letter", "title": "1997 Letter to Shareholders", "author": "Jeff Bezos", "date": "1998-04", "cat": "Girişim ve VC", "type": "mektup", "url": "https://s2.q4cdn.com/299287126/files/doc_financials/annual/Shareholderletter97.pdf", "pdf": true, "preview": true, "summary": "'Her şey uzun vadeyle ilgili' diyen ilk Amazon mektubu: kısa vadeli kâr yerine pazar liderliğine, müşteri takıntısına ve cesur yatırımlara odaklan. Bezos sonraki yıllarda bu mektubu her yıllık mektubuna ekledi.", "star": true}, {"id": "cargo-cult-science", "title": "Cargo Cult Science", "author": "Richard Feynman", "date": "1974-06", "cat": "Dünya görüşü", "type": "konuşma", "url": "https://calteches.library.caltech.edu/51/2/CargoCult.pdf", "pdf": true, "preview": true, "summary": "Bilimin biçimini taklit edip özünü kaçıran araştırmaları kargo kültlerine benzetiyor. İlk ilke: kendini kandırmamalısın, çünkü kandırması en kolay kişi sensin.", "star": true}, {"id": "disruptive-technologies", "title": "Disruptive Technologies: Catching the Wave", "author": "Joseph L. Bower & Clayton M. Christensen", "date": "1995-01", "cat": "Girişim ve VC", "type": "makale", "url": "https://hbr.org/1995/01/disruptive-technologies-catching-the-wave", "pdf": false, "preview": false, "summary": "İyi yönetilen şirketlerin, mevcut müşterilerini dinledikleri için başta daha kötü görünen yıkıcı teknolojileri kaçırdığını anlatıyor. 'Yıkıcı inovasyon' kavramını doğuran makale.", "star": true}, {"id": "moores-law-1965", "title": "Cramming More Components onto Integrated Circuits", "author": "Gordon E. Moore", "date": "1965-04", "cat": "Teknik makale", "type": "makale", "url": "https://www.cs.utexas.edu/~fussell/courses/cs352h/papers/moore.pdf", "pdf": true, "preview": false, "summary": "Bir çipteki bileşen sayısının her yıl kabaca ikiye katlanacağını öngören makale: Moore Yasası. Üstel gelişmenin ekonomisini ve neleri mümkün kılacağını ilk kez ortaya koyuyor.", "star": true}, {"id": "tragedy-of-the-commons", "title": "The Tragedy of the Commons", "author": "Garrett Hardin", "date": "1968-12", "cat": "Dünya görüşü", "type": "makale", "url": "https://pages.mtu.edu/~asmayer/rural_sustain/governance/Hardin%201968.pdf", "pdf": true, "preview": true, "summary": "Herkesin kullandığı ortak bir kaynağın, her bireyin kendi çıkarına göre rasyonel davranması yüzünden nasıl tükendiğini gösteriyor. Teknik çözümü olmayan problemler kavramını tartışmaya açıyor.", "star": true}, {"id": "tversky-kahneman-1974", "title": "Judgment under Uncertainty: Heuristics and Biases", "author": "Amos Tversky & Daniel Kahneman", "date": "1974-09", "cat": "Dünya görüşü", "type": "makale", "url": "https://sites.socsci.uci.edu/~bskyrms/bio/readings/tversky_k_heuristics_biases.pdf", "pdf": true, "preview": true, "summary": "İnsanların belirsizlik altında temsil edicilik, ulaşılabilirlik ve çapalama gibi kısayollarla karar verdiğini ve bunların sistematik hatalara yol açtığını gösteriyor. Davranışsal ekonominin kurucu makalelerinden biri.", "star": true}, {"id": "turing-on-computable-numbers", "title": "On Computable Numbers, with an Application to the Entscheidungsproblem", "author": "Alan Turing", "date": "1936", "cat": "Teknik makale", "type": "makale", "url": "https://www.cs.virginia.edu/~robins/Turing_Paper_1936.pdf", "pdf": true, "preview": true, "summary": "Hesaplamanın ne olduğunu basit bir hayali makineyle, Turing makinesiyle tanımlıyor ve her problemin mekanik olarak çözülemeyeceğini kanıtlıyor. Her modern bilgisayarın teorik temeli olan 'evrensel makine' fikri burada doğdu.", "star": true}, {"id": "codd-relational-model", "title": "A Relational Model of Data for Large Shared Data Banks", "author": "E. F. Codd", "date": "1970-06", "cat": "Teknik makale", "type": "makale", "url": "https://www.seas.upenn.edu/~zives/03f/cis550/codd.pdf", "pdf": true, "preview": true, "summary": "Veriyi fiziksel saklanma biçiminden ayırıp basit tablolar ve ilişkiler olarak modellemeyi öneriyor. SQL'in ve bugün kullanılan neredeyse bütün ilişkisel veritabanlarının çıkış noktası.", "star": true}, {"id": "lamport-time-clocks", "title": "Time, Clocks, and the Ordering of Events in a Distributed System", "author": "Leslie Lamport", "date": "1978-07", "cat": "Teknik makale", "type": "makale", "url": "https://lamport.azurewebsites.net/pubs/time-clocks.pdf", "pdf": true, "preview": true, "summary": "Ortak bir saatin olmadığı dağıtık sistemlerde olayları 'önce oldu' ilişkisiyle sıralamanın yolunu gösteriyor ve mantıksal saatleri tanımlıyor. Dağıtık sistemler alanının kurucu makalesi.", "star": true}, {"id": "google-mapreduce", "title": "MapReduce: Simplified Data Processing on Large Clusters", "author": "Jeffrey Dean & Sanjay Ghemawat", "date": "2004-12", "cat": "Teknik makale", "type": "makale", "url": "https://static.googleusercontent.com/media/research.google.com/en//archive/mapreduce-osdi04.pdf", "pdf": true, "preview": true, "summary": "Binlerce makinede devasa veriyi işlemeyi iki basit fonksiyona, map ve reduce'a indiriyor; hata toleransı ve dağıtımı sistem üstleniyor. Hadoop'u ve büyük veri çağını başlatan makale.", "star": true}, {"id": "google-file-system", "title": "The Google File System", "author": "Sanjay Ghemawat, Howard Gobioff & Shun-Tak Leung", "date": "2003-10", "cat": "Teknik makale", "type": "makale", "url": "https://static.googleusercontent.com/media/research.google.com/en//archive/gfs-sosp2003.pdf", "pdf": true, "preview": true, "summary": "Ucuz ve sık bozulan sıradan donanımla devasa ölçekte güvenilir depolama kurmanın yolunu anlatıyor: arızayı istisna değil, normal durum say. Bulut altyapısının tasarım felsefesini belirledi.", "star": true}, {"id": "amazon-dynamo", "title": "Dynamo: Amazon's Highly Available Key-value Store", "author": "Giuseppe DeCandia et al.", "date": "2007-10", "cat": "Teknik makale", "type": "makale", "url": "https://www.allthingsdistributed.com/files/amazon-dynamo-sosp2007.pdf", "pdf": true, "preview": true, "summary": "Sepete ekleme işleminin asla reddedilmemesi için tutarlılığı bilinçli olarak gevşetip erişilebilirliği öne alan bir veritabanını anlatıyor. Cassandra, Riak ve NoSQL dalgasına ilham verdi.", "star": true}, {"id": "parnas-modules", "title": "On the Criteria to Be Used in Decomposing Systems into Modules", "author": "David L. Parnas", "date": "1972-12", "cat": "Teknik makale", "type": "makale", "url": "https://wstomv.win.tue.nl/edu/2ip30/references/criteria_for_modularization.pdf", "pdf": true, "preview": true, "summary": "Bir sistemi iş akışının adımlarına göre değil, değişmesi muhtemel tasarım kararlarını saklayacak şekilde modüllere bölmeyi öneriyor. 'Bilgi gizleme' ilkesi ve modern yazılım mimarisinin temeli.", "star": true}, {"id": "backus-liberated-von-neumann", "title": "Can Programming Be Liberated from the von Neumann Style?", "author": "John Backus", "date": "1978-08", "cat": "Teknik makale", "type": "konuşma", "url": "https://www.cs.cmu.edu/~crary/819-f09/Backus78.pdf", "pdf": true, "preview": true, "summary": "FORTRAN'ın yaratıcısı, Turing Ödülü konuşmasında kendi kuşağının dillerini eleştiriyor: kelime kelime belleği güncelleyen programlama tıkanmıştır. Fonksiyonel programlamaya geniş kitlenin ilgisini çeken metin.", "star": true}, {"id": "lampson-hints-system-design", "title": "Hints for Computer System Design", "author": "Butler W. Lampson", "date": "1983-10", "cat": "Teknik makale", "type": "makale", "url": "https://bwlampson.site/33-Hints/Acrobat.pdf", "pdf": true, "preview": true, "summary": "Xerox PARC'ın efsane tasarımcısı, sistem kurarken işe yarayan sezgileri derliyor: basit tut, tek bir şeyi iyi yap, normal durumla en kötü durumu ayrı ele al. Onlarca yıldır mühendislerin başvuru metni.", "star": true}, {"id": "end-to-end-arguments", "title": "End-to-End Arguments in System Design", "author": "J. H. Saltzer, D. P. Reed & D. D. Clark", "date": "1984-11", "cat": "Teknik makale", "type": "makale", "url": "https://web.mit.edu/Saltzer/www/publications/endtoend/endtoend.pdf", "pdf": true, "preview": false, "summary": "Güvenilirlik gibi işlevlerin ancak iletişimin uç noktalarında tam olarak sağlanabileceğini, ağın ortasını basit tutmak gerektiğini savunuyor. İnternetin 'aptal ağ, akıllı uçlar' mimarisinin gerekçesi.", "star": true}, {"id": "yegge-platforms-rant", "title": "Stevey's Google Platforms Rant", "author": "Steve Yegge", "date": "2011-10", "cat": "Teknik makale", "type": "not", "url": "https://gist.github.com/chitchcock/1281611", "pdf": false, "preview": false, "summary": "Yanlışlıkla herkese açık paylaşılan iç not: Bezos'un Amazon'da her ekibi yalnızca servis arayüzleriyle konuşmaya zorlamasını anlatıyor ve Google'ın ürün yaptığını ama platform kuramadığını söylüyor. Platform düşüncesinin en ünlü savunusu.", "star": true}, {"id": "choose-boring-technology", "title": "Choose Boring Technology", "author": "Dan McKinley", "date": "2015-03", "cat": "Teknik makale", "type": "deneme", "url": "https://mcfunley.com/choose-boring-technology", "pdf": false, "preview": false, "summary": "Her şirketin sınırlı sayıda 'yenilik jetonu' olduğunu, bunları altyapıya değil ürünü farklılaştıran şeylere harcaman gerektiğini anlatıyor. Bilinen, sıkıcı teknolojinin bilinmeyen arıza biçimleri daha azdır.", "star": true}, {"id": "backprop-rumelhart-hinton-williams", "title": "Learning Representations by Back-propagating Errors", "author": "David E. Rumelhart, Geoffrey E. Hinton & Ronald J. Williams", "date": "1986-10", "cat": "Yapay zekâ", "type": "makale", "url": "https://www.cs.toronto.edu/~hinton/absps/naturebp.pdf", "pdf": true, "preview": true, "summary": "Çok katmanlı sinir ağlarının, hatayı geriye doğru yayarak gizli katmanlarda kendi iç temsillerini öğrenebileceğini gösteriyor. Bugünkü derin öğrenmenin tamamı bu eğitim yöntemine dayanıyor.", "star": true}, {"id": "lstm-hochreiter-schmidhuber", "title": "Long Short-Term Memory", "author": "Sepp Hochreiter & Jürgen Schmidhuber", "date": "1997-11", "cat": "Yapay zekâ", "type": "makale", "url": "https://www.bioinf.jku.at/publications/older/2604.pdf", "pdf": true, "preview": true, "summary": "Tekrarlayan ağların uzun bağlamları unutma sorununu, bilgiyi kapılarla koruyan bir hafıza hücresiyle çözüyor. Transformer'dan önce konuşma tanıma ve çeviride on yıl boyunca hâkim olan mimari.", "star": true}, {"id": "dqn-playing-atari", "title": "Playing Atari with Deep Reinforcement Learning", "author": "Volodymyr Mnih et al. (DeepMind)", "date": "2013-12", "cat": "Yapay zekâ", "type": "makale", "url": "https://www.cs.toronto.edu/~vmnih/docs/dqn.pdf", "pdf": true, "preview": true, "summary": "Tek bir ağın yalnızca ekran piksellerine ve skora bakarak Atari oyunlarını oynamayı öğrendiğini gösteriyor. Derin pekiştirmeli öğrenme dalgasını ve DeepMind'ın yükselişini başlatan çalışma.", "star": true}, {"id": "generative-adversarial-nets", "title": "Generative Adversarial Networks", "author": "Ian J. Goodfellow et al.", "date": "2014-06", "cat": "Yapay zekâ", "type": "makale", "url": "https://arxiv.org/pdf/1406.2661", "pdf": true, "preview": true, "summary": "Biri sahte örnek üreten, diğeri sahteyi gerçekten ayırmaya çalışan iki ağı birbirine karşı eğitme fikri. Gerçekçi görüntü üretiminin ilk büyük atılımı ve 'deepfake' çağının başlangıcı.", "star": true}, {"id": "bert", "title": "BERT: Pre-training of Deep Bidirectional Transformers for Language Understanding", "author": "Jacob Devlin, Ming-Wei Chang, Kenton Lee & Kristina Toutanova", "date": "2018-10", "cat": "Yapay zekâ", "type": "makale", "url": "https://arxiv.org/pdf/1810.04805", "pdf": true, "preview": true, "summary": "Büyük bir dil modelini önce etiketsiz metinde eksik kelimeleri tahmin ederek eğitip sonra her göreve az veriyle uyarlamayı gösteriyor. 'Önce ön eğitim, sonra ince ayar' kalıbını NLP'nin standardı yaptı.", "star": true}, {"id": "ddpm-diffusion", "title": "Denoising Diffusion Probabilistic Models", "author": "Jonathan Ho, Ajay Jain & Pieter Abbeel", "date": "2020-06", "cat": "Yapay zekâ", "type": "makale", "url": "https://arxiv.org/pdf/2006.11239", "pdf": true, "preview": true, "summary": "Görüntüyü adım adım gürültüye boğup modelin bu süreci tersine çevirmeyi öğrenmesiyle yüksek kaliteli görüntü üretiyor. Stable Diffusion, DALL·E 2 ve Midjourney'nin dayandığı yaklaşımı ana akıma taşıdı.", "star": true}, {"id": "chain-of-thought-prompting", "title": "Chain-of-Thought Prompting Elicits Reasoning in Large Language Models", "author": "Jason Wei et al.", "date": "2022-01", "cat": "Yapay zekâ", "type": "makale", "url": "https://arxiv.org/pdf/2201.11903", "pdf": true, "preview": true, "summary": "Büyük dil modellerine cevaptan önce ara adımları yazdırmanın matematik ve mantık sorularında başarıyı çarpıcı biçimde artırdığını gösteriyor. Bugünkü 'düşünen' akıl yürütme modellerinin habercisi.", "star": true}, {"id": "instructgpt", "title": "Training Language Models to Follow Instructions with Human Feedback (InstructGPT)", "author": "Long Ouyang et al. (OpenAI)", "date": "2022-03", "cat": "Yapay zekâ", "type": "makale", "url": "https://arxiv.org/pdf/2203.02155", "pdf": true, "preview": true, "summary": "İnsan tercihlerinden öğrenen pekiştirmeli öğrenmeyle (RLHF) ince ayar yapılan küçük bir modelin, yüz kat büyük GPT-3'ten daha çok tercih edildiğini gösteriyor. ChatGPT'yi mümkün kılan tarif.", "star": true}, {"id": "b-money", "title": "b-money", "author": "Wei Dai", "date": "1998-11", "cat": "Kripto", "type": "makale", "url": "https://nakamotoinstitute.org/library/b-money/", "pdf": false, "preview": false, "summary": "Takma adlı katılımcıların ortak bir defter tutarak hesaplama işiyle para yarattığı, devlete ihtiyaç duymayan bir elektronik nakit sistemi tarif ediyor. Satoshi'nin Bitcoin makalesinde ilk atıf yaptığı metin.", "star": true}, {"id": "bit-gold", "title": "Bit Gold", "author": "Nick Szabo", "date": "2005-12", "cat": "Kripto", "type": "deneme", "url": "https://nakamotoinstitute.org/library/bit-gold/", "pdf": false, "preview": false, "summary": "Altının değerini taklit eden dijital bir varlık öneriyor: üretimi maliyetli hesaplama işine dayanan, güvenilir üçüncü tarafa ihtiyaç duymayan kıt bitler. Bitcoin'in en yakın fikir atası.", "star": true}, {"id": "lightning-network", "title": "The Bitcoin Lightning Network: Scalable Off-Chain Instant Payments", "author": "Joseph Poon & Thaddeus Dryja", "date": "2016-01", "cat": "Kripto", "type": "makale", "url": "https://lightning.network/lightning-network-paper.pdf", "pdf": true, "preview": true, "summary": "Ödemelerin çoğunu zincir dışındaki kanallarda yapıp yalnızca sonucu zincire yazarak Bitcoin'i anlık ve ucuz mikro ödemelere ölçeklemeyi öneriyor. 'Katman 2' ölçekleme fikrinin kurucu belgesi.", "star": true}, {"id": "kelly-criterion", "title": "A New Interpretation of Information Rate", "author": "J. L. Kelly Jr.", "date": "1956-07", "cat": "Makro ve yatırım", "type": "makale", "url": "https://www.princeton.edu/~wbialek/rome/refs/kelly_56.pdf", "pdf": true, "preview": true, "summary": "Avantajın varsa sermayenin ne kadarını riske atman gerektiğini, uzun vadeli büyümeyi maksimize eden formülle veriyor: Kelly kriteri. Thorp'tan Buffett'a kadar pozisyon büyüklüğü düşüncesinin temeli.", "star": true}, {"id": "sharpe-arithmetic-active-management", "title": "The Arithmetic of Active Management", "author": "William F. Sharpe", "date": "1991-01", "cat": "Makro ve yatırım", "type": "makale", "url": "https://web.stanford.edu/~wfsharpe/art/active/active.htm", "pdf": false, "preview": false, "summary": "Basit bir aritmetikle, masraflar düşüldükten sonra aktif yönetilen ortalama paranın pasif yönetilen ortalama paradan daha az kazanmak zorunda olduğunu gösteriyor. Endeks fonu devriminin en kısa ve en sağlam gerekçesi.", "star": true}, {"id": "marks-most-important-thing", "title": "The Most Important Thing", "author": "Howard Marks", "date": "2003-07", "cat": "Makro ve yatırım", "type": "not", "url": "https://www.oaktreecapital.com/insights/memo/the-most-important-thing", "pdf": false, "preview": false, "summary": "Başarılı yatırım için 'en önemli şeyin' tek bir şey olmadığını, ikinci düzey düşünce, riskin farkında olmak ve döngüleri anlamak gibi birkaç ilkenin birlikte işlediğini anlatıyor. Buffett'ın övdüğü aynı adlı kitabın çekirdeği.", "star": true}, {"id": "munger-psychology-of-human-misjudgment", "title": "The Psychology of Human Misjudgment", "author": "Charlie Munger", "date": "1995-06", "cat": "Makro ve yatırım", "type": "konuşma", "url": "https://web.archive.org/web/20151004200748/http://law.indiana.edu/instruction/profession/doc/16_1.pdf", "pdf": true, "preview": true, "summary": "Teşvik etkisinden sosyal kanıta kadar insanı yanıltan 25 psikolojik eğilimi sıralıyor ve bunların birlikte çalıştığında felakete yol açtığını gösteriyor. Zihinsel modeller kavramının en ünlü metni.", "star": true}, {"id": "friedman-social-responsibility", "title": "The Social Responsibility of Business Is to Increase Its Profits", "author": "Milton Friedman", "date": "1970-09", "cat": "Makro ve yatırım", "type": "deneme", "url": "https://business.pitt.edu/wp-content/uploads/2025/02/25Right-Readings-Friedman-1.pdf", "pdf": true, "preview": true, "summary": "Yöneticinin hissedarların çalışanı olduğunu, onların parasını kendi seçtiği toplumsal hedeflere harcamasının bir tür vergilendirme olduğunu savunuyor. Hissedar değeri anlayışını şekillendiren, bugün de tartışılan makale.", "star": true}, {"id": "akerlof-market-for-lemons", "title": "The Market for \"Lemons\": Quality Uncertainty and the Market Mechanism", "author": "George A. Akerlof", "date": "1970-08", "cat": "Makro ve yatırım", "type": "makale", "url": "https://www.sfu.ca/~allen/Ackerlof.pdf", "pdf": true, "preview": true, "summary": "İkinci el araba örneğiyle, satıcı kaliteyi alıcıdan iyi bildiğinde kötü malların iyileri piyasadan kovabileceğini gösteriyor. Asimetrik bilgi kavramını yerleştiren, garantilerin ve markaların neden var olduğunu açıklayan çalışma.", "star": true}, {"id": "coase-nature-of-the-firm", "title": "The Nature of the Firm", "author": "Ronald H. Coase", "date": "1937-11", "cat": "Makro ve yatırım", "type": "makale", "url": "https://www.jstor.org/stable/2626876", "pdf": false, "preview": false, "summary": "Her şey piyasada alınıp satılabiliyorsa firmalar neden var diye soruyor ve cevabı işlem maliyetlerinde buluyor. Bir işi içeride yapma ile dışarıdan satın alma kararının arkasındaki temel mantık.", "star": true}, {"id": "porter-competitive-forces", "title": "How Competitive Forces Shape Strategy", "author": "Michael E. Porter", "date": "1979-03", "cat": "Girişim ve VC", "type": "makale", "url": "https://hbr.org/1979/03/how-competitive-forces-shape-strategy", "pdf": false, "preview": false, "summary": "Bir sektörün kârlılığını yalnızca rakiplerin değil; müşterilerin, tedarikçilerin, yeni girenlerin ve ikame ürünlerin gücünün belirlediğini gösteriyor. 'Beş Güç' modelini doğuran makale.", "star": true}, {"id": "levitt-marketing-myopia", "title": "Marketing Myopia", "author": "Theodore Levitt", "date": "1960-07", "cat": "Girişim ve VC", "type": "makale", "url": "https://hbr.org/2004/07/marketing-myopia", "pdf": false, "preview": false, "summary": "Demiryolu şirketlerinin kendilerini ulaşım işinde değil tren işinde gördükleri için çöktüğünü anlatıyor. Şirketini sattığın ürünle değil, karşıladığın müşteri ihtiyacıyla tanımlamanı söylüyor.", "star": true}, {"id": "core-competence-of-the-corporation", "title": "The Core Competence of the Corporation", "author": "C. K. Prahalad & Gary Hamel", "date": "1990-05", "cat": "Girişim ve VC", "type": "makale", "url": "https://hbr.org/1990/05/the-core-competence-of-the-corporation", "pdf": false, "preview": false, "summary": "Şirketi bir iş birimleri portföyü olarak değil, birçok ürüne yayılabilen temel yetkinliklerin bütünü olarak görmeyi öneriyor. Rekabet avantajının asıl kaynağının ürünler değil yetkinlikler olduğunu savunuyor.", "star": true}, {"id": "spolsky-strategy-letter-v", "title": "Strategy Letter V", "author": "Joel Spolsky", "date": "2002-06", "cat": "Girişim ve VC", "type": "deneme", "url": "https://www.joelonsoftware.com/2002/06/12/strategy-letter-v/", "pdf": false, "preview": false, "summary": "Akıllı şirketlerin, kendi ürünlerinin tamamlayıcılarını ucuzlatıp metalaştırarak talebi artırdığını anlatıyor. IBM'in açık PC mimarisinden şirketlerin açık kaynağa yatırımına kadar pek çok hamleyi açıklayan 'tamamlayıcını metalaştır' ilkesi.", "star": true}, {"id": "gates-open-letter-to-hobbyists", "title": "An Open Letter to Hobbyists", "author": "Bill Gates", "date": "1976-02", "cat": "Girişim ve VC", "type": "mektup", "url": "https://web.njit.edu/~evank/download/gates_letter.pdf", "pdf": true, "preview": true, "summary": "Genç Gates, hobicilerin BASIC'i parasını ödemeden kopyalamasına itiraz ediyor ve emeğin karşılığı alınmazsa kimsenin iyi yazılım yazmayacağını söylüyor. Yazılımın ayrı bir ürün olarak satılabileceği fikrinin manifestosu.", "star": true}, {"id": "jobs-thoughts-on-flash", "title": "Thoughts on Flash", "author": "Steve Jobs", "date": "2010-04", "cat": "Girişim ve VC", "type": "mektup", "url": "https://web.archive.org/web/20100501010616/http://www.apple.com/hotnews/thoughts-on-flash/", "pdf": false, "preview": false, "summary": "Jobs, iPhone ve iPad'in neden Flash'ı desteklemeyeceğini açık standartlar, güvenlik, pil ömrü ve dokunmatik arayüz gerekçeleriyle anlatıyor. Mobil web'in HTML5'e geçişini hızlandıran ve platform sahipliğinin gücünü gösteren mektup.", "star": true}, {"id": "granovetter-strength-of-weak-ties", "title": "The Strength of Weak Ties", "author": "Mark S. Granovetter", "date": "1973-05", "cat": "Dünya görüşü", "type": "makale", "url": "https://snap.stanford.edu/class/cs224w-readings/granovetter73weakties.pdf", "pdf": true, "preview": true, "summary": "Yeni iş ve fırsat bilgisinin çoğunlukla yakın arkadaşlardan değil, uzak tanıdıklardan geldiğini gösteriyor; çünkü zayıf bağlar farklı çevreler arasında köprü kurar. Sosyal ağ biliminin en çok atıf alan makalelerinden.", "star": true}, {"id": "meadows-leverage-points", "title": "Leverage Points: Places to Intervene in a System", "author": "Donella Meadows", "date": "1999", "cat": "Dünya görüşü", "type": "deneme", "url": "https://www.donellameadows.org/wp-content/userfiles/Leverage_Points.pdf", "pdf": true, "preview": true, "summary": "Bir sistemi değiştirmek için müdahale edilebilecek noktaları etkisi artan sırayla diziyor: parametrelerden geri besleme döngülerine, hedeflere ve en tepedeki paradigmaya kadar. Sistem düşüncesinin en pratik özeti.", "star": true}, {"id": "orwell-politics-english-language", "title": "Politics and the English Language", "author": "George Orwell", "date": "1946-04", "cat": "Dünya görüşü", "type": "deneme", "url": "https://www.orwellfoundation.com/the-orwell-foundation/orwell/essays-and-other-works/politics-and-the-english-language/", "pdf": false, "preview": false, "summary": "Bulanık ve kalıp ifadelerle dolu dilin bulanık düşünceye yol açtığını, siyasetin bunu gerçeği örtmek için kullandığını gösteriyor. Sonundaki altı yazım kuralı hâlâ net yazının en iyi rehberi.", "star": true}, {"id": "asimov-new-ideas", "title": "On Creativity (How Do People Get New Ideas?)", "author": "Isaac Asimov", "date": "1959", "cat": "Dünya görüşü", "type": "deneme", "url": "https://www.technologyreview.com/2014/10/20/169899/isaac-asimov-asks-how-do-people-get-new-ideas/", "pdf": false, "preview": false, "summary": "Asimov'un ABD'nin bir savunma araştırma projesi için yazdığı ancak 2014'e kadar yayımlanmamış notu: yeni fikirler, ilgisiz alanları birleştirebilen ve saçma görünmekten korkmayan insanlardan gelir. Küçük, rahat ve baskısız grupların yaratıcılığı nasıl beslediğini anlatıyor.", "star": true}, {"id": "read-i-pencil", "title": "I, Pencil", "author": "Leonard E. Read", "date": "1958-12", "cat": "Dünya görüşü", "type": "deneme", "url": "https://fee.org/ebooks/i-pencil", "pdf": false, "preview": false, "summary": "Sıradan bir kurşun kalemin ağzından, dünyada tek başına onu yapmayı bilen kimsenin olmadığını, milyonlarca insanın merkezi bir plan olmadan iş birliğiyle onu ürettiğini anlatıyor. Piyasanın 'görünmez el'ini anlatan en sade hikâye.", "star": true}, {"id": "bastiat-seen-and-unseen", "title": "That Which Is Seen and That Which Is Not Seen", "author": "Frédéric Bastiat", "date": "1850-07", "cat": "Dünya görüşü", "type": "deneme", "url": "https://fee.org/resources/that-which-is-seen-and-that-which-is-not-seen/", "pdf": false, "preview": false, "summary": "Kırık cam örneğiyle, bir kararın hemen görülen etkisine bakıp görünmeyen fırsat maliyetini unutmanın kötü ekonominin kökü olduğunu gösteriyor. İkinci düzey düşüncenin 175 yıllık klasiği.", "star": true}, {"id": "prospect-theory", "title": "Prospect Theory: An Analysis of Decision under Risk", "author": "Daniel Kahneman & Amos Tversky", "date": "1979-03", "cat": "Dünya görüşü", "type": "makale", "url": "https://web.mit.edu/curhan/www/docs/Articles/15341_Readings/Behavioral_Decision_Theory/Kahneman_Tversky_1979_Prospect_theory.pdf", "pdf": true, "preview": false, "summary": "İnsanların kararlarını toplam servete göre değil kazanç ve kayıplara göre verdiğini, kaybın acısının eşit kazancın sevincinden daha güçlü olduğunu gösteriyor. Davranışsal ekonominin kurucu makalesi ve Kahneman'ın Nobel'inin temeli.", "star": true}, {"id": "hayek-use-of-knowledge", "title": "The Use of Knowledge in Society", "author": "Friedrich A. Hayek", "date": "1945-09", "cat": "Dünya görüşü", "type": "makale", "url": "https://www.laits.utexas.edu/~mbs31415/HayekUseOfKnowledgeInSociety.pdf", "pdf": true, "preview": true, "summary": "Ekonomik sorunun, hiçbir merkezin bir arada tutamayacağı dağınık yerel bilginin nasıl kullanılacağı olduğunu, fiyatların bu bilgiyi taşıyan bir iletişim sistemi gibi çalıştığını savunuyor. Merkezi planlamaya karşı en güçlü argüman.", "star": true}, {"id": "drucker-managing-oneself", "title": "Managing Oneself", "author": "Peter F. Drucker", "date": "1999-03", "cat": "Dünya görüşü", "type": "makale", "url": "https://hbr.org/2005/01/managing-oneself", "pdf": false, "preview": false, "summary": "Bilgi çağında kariyerini şirketin değil kendinin yönetmesi gerektiğini söylüyor: güçlü yanların neler, nasıl öğreniyorsun, değerlerin ne, nereye aitsin? Kendini tanımak için hâlâ en iyi soru listesi.", "star": true}, {"id": "porter-what-is-strategy", "title": "What Is Strategy?", "author": "Michael E. Porter", "date": "1996", "cat": "Girişim ve VC", "type": "makale", "url": "https://hbr.org/1996/11/what-is-strategy", "pdf": false, "preview": false, "summary": "Operasyonel verimliliğin strateji olmadığını savunuyor: strateji, rakiplerden farklı bir faaliyetler bütünü seçmek, ödünleşimleri kabul etmek ve bu faaliyetleri birbirine uydurmaktır. Neyi yapmayacağını seçmek stratejinin özüdür.", "star": true}, {"id": "drucker-theory-of-the-business", "title": "The Theory of the Business", "author": "Peter F. Drucker", "date": "1994", "cat": "Girişim ve VC", "type": "makale", "url": "https://hbr.org/1994/09/the-theory-of-the-business", "pdf": false, "preview": false, "summary": "Her şirketin çevre, misyon ve temel yetkinlikler hakkındaki varsayımlardan oluşan bir 'iş teorisi' olduğunu; büyük şirketlerin çoğu zaman kötü yönetimden değil, bu teori gerçeğe uymaz hale geldiği için çöktüğünü anlatıyor. Teoriyi düzenli olarak sınamayı öneriyor.", "star": true}, {"id": "netflix-culture-freedom-responsibility", "title": "Netflix Culture: Freedom & Responsibility", "author": "Reed Hastings / Netflix", "date": "2009 (2020 sürümü)", "cat": "Girişim ve VC", "type": "not", "url": "https://web.archive.org/web/20201230090827/https://jobs.netflix.com/culture", "pdf": false, "preview": false, "summary": "Kuralları azaltıp yetenek yoğunluğunu artırmayı, 'kontrol değil bağlam' vermeyi ve 'keeper test' gibi ilkelerle özgürlük ve sorumluluk kültürü kurmayı anlatıyor. 2009'daki ilk sunumu Silikon Vadisi'nin en çok paylaşılan kültür belgesi oldu.", "star": true}, {"id": "bezos-2017-letter", "title": "2017 Letter to Shareholders (High Standards)", "author": "Jeff Bezos", "date": "2018", "cat": "Girişim ve VC", "type": "mektup", "url": "https://www.aboutamazon.com/news/company-news/2017-letter-to-shareholders", "pdf": false, "preview": false, "summary": "Yüksek standartların doğuştan değil öğretilebilir ve alana özgü olduğunu, iyi bir işin ne kadar emek istediğine dair gerçekçi bir beklenti gerektirdiğini anlatıyor. Amazon'un sunum yerine neden altı sayfalık anlatı notları kullandığını da açıklıyor.", "star": true}, {"id": "gurley-all-revenue-not-equal", "title": "All Revenue Is Not Created Equal: The Keys to the 10X Revenue Club", "author": "Bill Gurley", "date": "2011", "cat": "Girişim ve VC", "type": "deneme", "url": "https://abovethecrowd.com/2011/05/24/all-revenue-is-not-created-equal-the-keys-to-the-10x-revenue-club/", "pdf": false, "preview": false, "summary": "Aynı gelire sahip iki şirketin neden çok farklı değerlendiğini; sürdürülebilir rekabet avantajı, ağ etkisi, gelirin öngörülebilirliği, müşteri bağımlılığı ve brüt marj gibi ölçütlerle açıklıyor. Gelir çarpanına bakmadan önce gelirin kalitesine bakmayı öğretiyor.", "star": true}, {"id": "eugene-wei-status-as-a-service", "title": "Status as a Service (StaaS)", "author": "Eugene Wei", "date": "2019", "cat": "Girişim ve VC", "type": "deneme", "url": "https://www.eugenewei.com/blog/2019/2/19/status-as-a-service", "pdf": false, "preview": false, "summary": "Sosyal ağları insanların statü arayışı üzerinden okuyor: başarılı ağlar kullanıcılarına zorlu ama kazanılabilir bir statü oyunu ve görünür bir sosyal sermaye sunar. Ağların neden yükselip neden durgunlaştığını açıklayan güçlü bir çerçeve.", "star": true}, {"id": "shirky-group-worst-enemy", "title": "A Group Is Its Own Worst Enemy", "author": "Clay Shirky", "date": "2003", "cat": "Dünya görüşü", "type": "konuşma", "url": "https://web.archive.org/web/2005/http://www.shirky.com/writings/group_enemy.html", "pdf": false, "preview": false, "summary": "Çevrimiçi toplulukların dışarıdan değil, kendi içlerinden doğan tekrar eden grup davranışlarıyla bozulduğunu; bu yüzden sosyal yazılımın kimlik, üyelik ve yönetişim yapılarına ihtiyaç duyduğunu anlatıyor. Topluluk kuranların hâlâ başvurduğu metin.", "star": true}, {"id": "pg-keep-your-identity-small", "title": "Keep Your Identity Small", "author": "Paul Graham", "date": "2009", "cat": "Dünya görüşü", "type": "deneme", "url": "https://paulgraham.com/identity.html", "pdf": false, "preview": false, "summary": "Siyaset ve din tartışmalarının neden bu kadar verimsiz olduğunu açıklıyor: insanlar kimliklerinin parçası haline gelmiş konularda net düşünemez. Kimliğine ne kadar az şey katarsan o kadar açık düşünürsün.", "star": true}, {"id": "jensen-meckling-theory-of-the-firm", "title": "Theory of the Firm: Managerial Behavior, Agency Costs and Ownership Structure", "author": "Michael C. Jensen & William H. Meckling", "date": "1976", "cat": "Makro ve yatırım", "type": "makale", "url": "https://josephmahoney.web.illinois.edu/BA549_Fall%202012/Session%205/5_Jensen_Meckling%20(1976).pdf", "pdf": true, "preview": true, "summary": "Yöneticiler (vekil) ile hissedarlar (asil) arasındaki çıkar çatışmasının doğurduğu 'vekâlet maliyetlerini' tanımlıyor; sahiplik yapısının, borcun ve denetimin bu maliyetleri nasıl şekillendirdiğini gösteriyor. Hisse bazlı ücretlendirmeden kurumsal yönetişime kadar pek çok uygulamanın teorik temeli.", "star": true}, {"id": "coase-problem-of-social-cost", "title": "The Problem of Social Cost", "author": "Ronald H. Coase", "date": "1960", "cat": "Makro ve yatırım", "type": "makale", "url": "https://www.law.uchicago.edu/sites/default/files/file/coase-problem.pdf", "pdf": true, "preview": true, "summary": "Dışsallıkların tek taraflı bir zarar değil karşılıklı bir sorun olduğunu; işlem maliyetleri sıfır olsaydı hakların kime verildiğinden bağımsız olarak pazarlıkla verimli sonuca ulaşılacağını gösteriyor (Coase teoremi). Asıl dersi: gerçek dünyada işlem maliyetleri belirleyicidir.", "star": true}, {"id": "spence-job-market-signaling", "title": "Job Market Signaling", "author": "Michael Spence", "date": "1973", "cat": "Makro ve yatırım", "type": "makale", "url": "https://www.sfu.ca/%7Eallen/Spence.pdf", "pdf": true, "preview": true, "summary": "İşverenin adayın verimliliğini doğrudan göremediği durumda eğitim gibi maliyetli sinyallerin işe yaradığını, çünkü bu sinyalin yetenekli kişi için daha ucuz olduğunu gösteriyor. Diplomadan marka harcamasına kadar sinyal teorisinin temeli; 2001 Nobel'ine giden çalışma.", "star": true}, {"id": "grossman-stiglitz-impossibility", "title": "On the Impossibility of Informationally Efficient Markets", "author": "Sanford J. Grossman & Joseph E. Stiglitz", "date": "1980", "cat": "Makro ve yatırım", "type": "makale", "url": "https://www.aeaweb.org/aer/top20/70.3.393-408.pdf", "pdf": true, "preview": false, "summary": "Fiyatlar tüm bilgiyi kusursuz yansıtsaydı kimse bilgi toplamaya para harcamazdı; bu yüzden piyasalar tam etkin olamaz ve bilgi toplayanı ödüllendirecek kadar verimsizlik kalmalıdır. Aktif yatırımcılığın neden var olduğunu açıklayan paradoks.", "star": true}, {"id": "fama-efficient-capital-markets", "title": "Efficient Capital Markets: A Review of Theory and Empirical Work", "author": "Eugene F. Fama", "date": "1970", "cat": "Makro ve yatırım", "type": "makale", "url": "https://www.jstor.org/stable/2325486", "pdf": false, "preview": false, "summary": "Etkin piyasa hipotezini zayıf, yarı güçlü ve güçlü formlara ayırıp dönemin kanıtlarını gözden geçiriyor; fiyatların mevcut bilgiyi hızla yansıttığı sonucuna varıyor. Endeks fonu devriminin akademik dayanağı.", "star": true}, {"id": "friedman-role-of-monetary-policy", "title": "The Role of Monetary Policy", "author": "Milton Friedman", "date": "1968", "cat": "Makro ve yatırım", "type": "konuşma", "url": "https://www.aeaweb.org/aer/top20/58.1.1-17.pdf", "pdf": true, "preview": false, "summary": "Para politikasının işsizliği kalıcı olarak 'doğal oranın' altında tutamayacağını, çünkü enflasyon beklentilerinin uyum sağlayacağını savunuyor. Enflasyon ile işsizlik arasındaki ödünleşimin kalıcı olmadığını 1970'lerin stagflasyonundan önce öngördü.", "star": true}, {"id": "fisher-debt-deflation", "title": "The Debt-Deflation Theory of Great Depressions", "author": "Irving Fisher", "date": "1933", "cat": "Makro ve yatırım", "type": "makale", "url": "https://fraser.stlouisfed.org/files/docs/meltzer/fisdeb33.pdf", "pdf": true, "preview": false, "summary": "Büyük bunalımların aşırı borçlanma ile deflasyonun birbirini beslemesinden doğduğunu anlatıyor: borç ödemek için yapılan zorunlu satışlar fiyatları düşürür, bu da borcun reel yükünü artırır. Minsky'den 2008 krizine kadar borç dinamikleri düşüncesinin kaynağı.", "star": true}, {"id": "romer-endogenous-technological-change", "title": "Endogenous Technological Change", "author": "Paul M. Romer", "date": "1990", "cat": "Makro ve yatırım", "type": "makale", "url": "https://web.stanford.edu/~klenow/Romer_1990.pdf", "pdf": true, "preview": true, "summary": "Teknolojik ilerlemeyi dışarıdan gelen bir şans değil, kâr güdüsüyle yapılan araştırmanın ürünü olarak modelliyor; fikirler aynı anda herkesçe kullanılabildiği için büyümenin artan getirilerle sürebileceğini gösteriyor. 2018 Nobel'ine giden makale.", "star": true}, {"id": "smith-division-of-labour", "title": "The Wealth of Nations, Book I, Ch. 1: Of the Division of Labour", "author": "Adam Smith", "date": "1776", "cat": "Makro ve yatırım", "type": "deneme", "url": "https://www.marxists.org/reference/archive/smith-adam/works/wealth-of-nations/book01/ch01.htm", "pdf": false, "preview": false, "summary": "Toplu iğne atölyesi örneğiyle iş bölümünün verimliliği nasıl katladığını anlatıyor: tek başına günde yirmi iğne bile yapamayacak işçiler, işi on sekiz kadar adıma bölünce on kişi günde 48.000 iğne üretiyor. Uzmanlaşma düşüncesinin başlangıç noktası.", "star": true}, {"id": "ricardo-comparative-advantage", "title": "On the Principles of Political Economy, Ch. 7: On Foreign Trade", "author": "David Ricardo", "date": "1817", "cat": "Makro ve yatırım", "type": "deneme", "url": "https://www.marxists.org/reference/subject/economics/ricardo/tax/ch07.htm", "pdf": false, "preview": false, "summary": "İngiltere ile Portekiz'in kumaş ve şarap örneğiyle, bir ülke her iki malı da daha verimli üretse bile ticaretin iki taraf için kazançlı olduğunu gösteriyor: herkes görece en iyi olduğu işte uzmanlaşmalı. Karşılaştırmalı üstünlük fikrinin kaynağı.", "star": true}, {"id": "keynes-general-theory-ch12", "title": "The General Theory, Ch. 12: The State of Long-Term Expectation", "author": "John Maynard Keynes", "date": "1936", "cat": "Makro ve yatırım", "type": "deneme", "url": "https://www.marxists.org/reference/subject/economics/keynes/general-theory/ch12.htm", "pdf": false, "preview": false, "summary": "Uzun vadeli yatırımın ölçülemeyen bir belirsizlik altında yapıldığını, borsanın başkalarının ne düşüneceğini tahmin etmeye dayanan bir 'güzellik yarışmasına' dönüştüğünü ve girişimin büyük ölçüde 'hayvansal güdülerle' yürüdüğünü anlatıyor. Spekülasyon ile girişimi ayıran bölüm.", "star": true}, {"id": "mises-economic-calculation", "title": "Economic Calculation in the Socialist Commonwealth", "author": "Ludwig von Mises", "date": "1920", "cat": "Makro ve yatırım", "type": "makale", "url": "https://web.archive.org/web/20141117054914/https://mises.org/pdf/econcalc.pdf", "pdf": true, "preview": true, "summary": "Üretim araçlarında özel mülkiyet ve piyasa fiyatları olmadan kaynakların rasyonel biçimde dağıtılamayacağını, çünkü hangi kullanımın daha değerli olduğunu hesaplayacak bir ölçü kalmayacağını savunuyor. 'Sosyalist hesaplama tartışmasını' başlatan makale.", "star": true}, {"id": "buffett-inflation-swindles-equity-investor", "title": "How Inflation Swindles the Equity Investor", "author": "Warren Buffett", "date": "1977", "cat": "Makro ve yatırım", "type": "makale", "url": "https://fortune.com/2011/06/12/buffett-how-inflation-swindles-the-equity-investor-fortune-classics-1977/", "pdf": false, "preview": false, "summary": "Hisse senetlerinin aslında özsermaye getirisi yaklaşık yüzde 12'de takılı kalan, tahvile benzer araçlar olduğunu; enflasyonun bu getiriyi yükseltmediğini ve vergiyle birleşince yatırımcının reel getirisini erittiğini gösteriyor.", "star": true}, {"id": "buffett-1999-stock-market", "title": "Mr. Buffett on the Stock Market", "author": "Warren Buffett (Carol Loomis ile)", "date": "1999", "cat": "Makro ve yatırım", "type": "makale", "url": "https://web.archive.org/web/20170116141028/http://archive.fortune.com/magazines/fortune/fortune_archive/1999/11/22/269071/index.htm", "pdf": false, "preview": false, "summary": "Dot-com zirvesinde, uzun dönem hisse getirilerini faiz oranlarının ve kurumsal kârların ekonomideki payının belirlediğini, yatırımcı beklentilerinin gerçekçi olmadığını gösteriyor. Otomobil ve havacılık örnekleriyle dünyayı dönüştüren bir sektörün yatırımcısını zengin etmeyebileceğini hatırlatıyor.", "star": true}, {"id": "marks-bubble-com", "title": "bubble.com", "author": "Howard Marks", "date": "2000", "cat": "Makro ve yatırım", "type": "not", "url": "https://www.oaktreecapital.com/docs/default-source/memos/2000-01-02-bubble.pdf", "pdf": true, "preview": true, "summary": "Edward Chancellor'ın spekülasyon tarihinden yola çıkarak internet ve teknoloji hisselerindeki çılgınlığı tarihî balonlarla karşılaştırıyor. Balonun patlamasından kısa süre önce yazıldı ve Marks'ın memolarını ünlü yaptı.", "star": true}, {"id": "marks-you-cant-predict-you-can-prepare", "title": "You Can't Predict. You Can Prepare.", "author": "Howard Marks", "date": "2001", "cat": "Makro ve yatırım", "type": "not", "url": "https://www.oaktreecapital.com/docs/default-source/memos/2001-11-20-you-cant-predict-you-can-prepare.pdf", "pdf": true, "preview": true, "summary": "Makro geleceği kimsenin tutarlı biçimde tahmin edemeyeceğini, ama döngünün neresinde olduğumuzu anlayıp portföyü buna göre hazırlayabileceğimizi savunuyor. Yatırımcılığın en kullanışlı ayrımlarından birini kuruyor.", "star": true}, {"id": "mauboussin-measuring-the-moat", "title": "Measuring the Moat: Assessing the Magnitude and Sustainability of Value Creation", "author": "Michael J. Mauboussin & Dan Callahan", "date": "2002 (2024 güncellemesi)", "cat": "Makro ve yatırım", "type": "makale", "url": "https://web.archive.org/web/20241027030853/https://www.morganstanley.com/im/publication/insights/articles/article_measuringthemoat.pdf", "pdf": true, "preview": true, "summary": "Bir şirketin sermaye maliyetinin üzerinde getiriyi ne kadar büyük ve ne kadar uzun süre sürdürebileceğini ölçmek için sektör yapısı, rekabet konumu ve değer zinciri analizlerini bir kontrol listesinde topluyor. 'Ekonomik hendek' kavramını ölçülebilir hale getiren rehber.", "star": true}, {"id": "dalio-how-the-economic-machine-works", "title": "How the Economic Machine Works", "author": "Ray Dalio", "date": "2013", "cat": "Makro ve yatırım", "type": "makale", "url": "https://economicprinciples.org/how-the-economic-machine-works", "pdf": false, "preview": false, "summary": "Ekonomiyi işlemlerin, kısa vadeli borç döngüsünün, uzun vadeli borç döngüsünün ve verimlilik artışının üst üste binmesi olarak anlatan sade bir model. Borç azaltımının hangi politika karışımıyla 'güzel', yani acısız olabileceğini açıklıyor.", "star": true}, {"id": "munger-elementary-worldly-wisdom", "title": "A Lesson on Elementary, Worldly Wisdom As It Relates To Investment Management & Business", "author": "Charlie Munger", "date": "1994", "cat": "Makro ve yatırım", "type": "konuşma", "url": "https://web.archive.org/web/20101202151547/http://ycombinator.com/munger.html", "pdf": false, "preview": false, "summary": "Tek tek bilgileri ezberlemek yerine farklı disiplinlerden alınmış zihinsel modellerden bir 'kafes' kurmayı; yatırımda az sayıda büyük ve iyi anlaşılmış fırsata odaklanmayı anlatıyor. 'Zihinsel modeller' kavramını yaygınlaştıran konuşma.", "star": true}, {"id": "szabo-social-scalability", "title": "Money, Blockchains, and Social Scalability", "author": "Nick Szabo", "date": "2017", "cat": "Kripto", "type": "deneme", "url": "https://unenumerated.blogspot.com/2017/02/money-blockchains-and-social-scalability.html", "pdf": false, "preview": false, "summary": "Bir kurumun kaç yabancıyı işbirliğine katabildiğini 'sosyal ölçeklenebilirlik' olarak tanımlıyor; blokzincirlerin hesaplama verimliliğini bilerek feda edip güven ihtiyacını azalttığını ve asıl değerlerinin bundan geldiğini savunuyor.", "star": true}, {"id": "szabo-trusted-third-parties", "title": "Trusted Third Parties Are Security Holes", "author": "Nick Szabo", "date": "2001", "cat": "Kripto", "type": "deneme", "url": "https://nakamotoinstitute.org/library/trusted-third-parties/", "pdf": false, "preview": false, "summary": "Güvenilir bir aracıya dayanan her protokolün o aracı kadar kırılgan ve pahalı olduğunu; iyi protokol tasarımının bu güven açıklarını en aza indirmek olduğunu savunuyor. Bitcoin'in felsefi öncüllerinden.", "star": true}, {"id": "may-crypto-anarchist-manifesto", "title": "The Crypto Anarchist Manifesto", "author": "Timothy C. May", "date": "1988", "cat": "Kripto", "type": "deneme", "url": "https://www.activism.net/cypherpunk/crypto-anarchy.html", "pdf": false, "preview": false, "summary": "Açık anahtarlı kriptografinin anonim iletişimi ve işlemi mümkün kılarak devletlerin vergi, denetim ve bilgi kontrolünü aşındıracağını öngörüyor. Cypherpunk hareketinin kurucu metinlerinden.", "star": true}, {"id": "singer-famine-affluence-morality", "title": "Famine, Affluence, and Morality", "author": "Peter Singer", "date": "1972", "cat": "Dünya görüşü", "type": "makale", "url": "https://web.archive.org/web/20110105104456/http://www.utilitarian.net/singer/by/1972----.htm", "pdf": false, "preview": false, "summary": "Gölde boğulan çocuk örneğiyle, ahlaki açıdan benzer önemde bir şeyi feda etmeden kötü bir şeyi önleyebiliyorsak bunu yapmakla yükümlü olduğumuzu ve uzaklığın bu yükümlülüğü değiştirmediğini savunuyor. Etkili özgecilik hareketinin fikrî kökü.", "star": true}, {"id": "kant-what-is-enlightenment", "title": "An Answer to the Question: What Is Enlightenment?", "author": "Immanuel Kant", "date": "1784", "cat": "Dünya görüşü", "type": "deneme", "url": "https://germanhistorydocs.org/en/the-holy-roman-empire-1648-1815/immanuel-kant-quot-what-is-enlightenment-quot-1784.pdf", "pdf": true, "preview": true, "summary": "Aydınlanmayı insanın kendi suçu olan ergin olmama halinden, yani aklını başkasının yönlendirmesi olmadan kullanamamaktan çıkışı olarak tanımlıyor. 'Sapere aude: aklını kullanma cesaretini göster' çağrısının kaynağı.", "star": true}, {"id": "emerson-self-reliance", "title": "Self-Reliance", "author": "Ralph Waldo Emerson", "date": "1841", "cat": "Dünya görüşü", "type": "deneme", "url": "https://www.stephenhicks.org/wp-content/uploads/2022/03/EmersonRalph-Self-Reliance-1841.pdf", "pdf": true, "preview": true, "summary": "Kendi düşüncene güvenmeyi, uyumculuktan ve geçmişte söylediklerinle tutarlı kalma takıntısından kurtulmayı savunuyor ('aptalca bir tutarlılık küçük zihinlerin umacısıdır'). Bireysel bağımsızlığın en etkili manifestolarından.", "star": true}, {"id": "dfw-this-is-water", "title": "This Is Water (Kenyon College Commencement Speech)", "author": "David Foster Wallace", "date": "2005", "cat": "Dünya görüşü", "type": "konuşma", "url": "https://web.archive.org/web/20081220011705/http://www.marginalia.org/dfw_kenyon_commencement.html", "pdf": false, "preview": false, "summary": "Eğitimin asıl değerinin neye dikkat edeceğini ve nasıl düşüneceğini seçebilmek olduğunu; bunu yapmazsan her şeyin merkezinde kendini gördüğün bir 'varsayılan ayarda' yaşayacağını anlatıyor. Suyun farkında olmayan balıklar metaforuyla.", "star": true}, {"id": "gopen-science-of-scientific-writing", "title": "The Science of Scientific Writing", "author": "George D. Gopen & Judith A. Swan", "date": "1990", "cat": "Dünya görüşü", "type": "makale", "url": "https://cseweb.ucsd.edu/~swanson/papers/science-of-writing.pdf", "pdf": true, "preview": true, "summary": "Okurun bilgiyi cümlede nerede aramayı beklediğine göre yazmayı öğretiyor: bağlam veren eski bilgi başa, vurgulanacak yeni bilgi cümle sonuna, özne ile fiil birbirine yakın. Teknik ve iş yazımının en etkili rehberlerinden.", "star": true}, {"id": "von-neumann-edvac", "title": "First Draft of a Report on the EDVAC", "author": "John von Neumann", "date": "1945-06", "cat": "Teknik makale", "type": "rapor", "url": "https://web.mit.edu/sts.035/www/PDFs/edvac.pdf", "pdf": true, "preview": false, "summary": "Program ile verinin aynı bellekte tutulduğu 'depolanmış program' bilgisayar mimarisini ilk kez sistemli biçimde tarif eden rapor. Bugün hâlâ 'von Neumann mimarisi' denen işlemci-bellek düzeninin kaynağı.", "star": true}, {"id": "mcculloch-pitts-1943", "title": "A Logical Calculus of the Ideas Immanent in Nervous Activity", "author": "Warren S. McCulloch & Walter Pitts", "date": "1943", "cat": "Yapay zekâ", "type": "makale", "url": "https://www.cs.cmu.edu/~epxing/Class/10715/reading/McCulloch.and.Pitts.pdf", "pdf": true, "preview": true, "summary": "Nöronu açık/kapalı çalışan basit bir mantık birimi olarak modelliyor ve bu birimlerden kurulan ağların mantıksal işlemleri hesaplayabileceğini gösteriyor. Yapay sinir ağlarının ilk matematiksel modeli.", "star": true}, {"id": "rosenblatt-perceptron", "title": "The Perceptron: A Probabilistic Model for Information Storage and Organization in the Brain", "author": "Frank Rosenblatt", "date": "1958", "cat": "Yapay zekâ", "type": "makale", "url": "https://homepages.math.uic.edu/~lreyzin/papers/rosenblatt58.pdf", "pdf": true, "preview": true, "summary": "Bağlantı ağırlıklarını deneyimle ayarlayarak örüntü tanımayı öğrenen bir makine, perceptron önerisi. 'Makine kurallarla programlanmak yerine örneklerden öğrenebilir' fikrinin, yani bugünkü derin öğrenmenin atası.", "star": true}, {"id": "hoare-emperors-old-clothes", "title": "The Emperor's Old Clothes", "author": "C. A. R. Hoare", "date": "1980", "cat": "Teknik makale", "type": "konuşma", "url": "https://www.labouseur.com/projects/codeReckon/papers/The-Emperors-Old-Clothes.pdf", "pdf": true, "preview": true, "summary": "Turing Ödülü konuşmasında Hoare, karmaşıklığın güvenilirliğin düşmanı olduğunu kendi başarısız projeleri üzerinden anlatıyor. Ünlü tespiti: bir tasarımı ya bariz hatası olmayacak kadar karmaşık ya da hatasız olduğu bariz olacak kadar basit yapabilirsiniz.", "star": true}, {"id": "dijkstra-cruelty-teaching-cs", "title": "On the Cruelty of Really Teaching Computing Science (EWD1036)", "author": "Edsger W. Dijkstra", "date": "1988-12", "cat": "Teknik makale", "type": "deneme", "url": "https://www.cs.utexas.edu/~EWD/ewd10xx/EWD1036.PDF", "pdf": true, "preview": false, "summary": "Dijkstra, bilgisayarların 'radikal bir yenilik' olduğunu, onları tanıdık benzetmelerle anlamaya çalışmanın yanıltıcı olduğunu savunuyor. Programlamayı deneme-yanılma değil, biçimsel akıl yürütme ve doğruluk kanıtı işi olarak öğretmeyi öneriyor.", "star": true}, {"id": "knuth-programming-as-art", "title": "Computer Programming as an Art", "author": "Donald E. Knuth", "date": "1974-12", "cat": "Teknik makale", "type": "konuşma", "url": "https://www.paulgraham.com/knuth.html", "pdf": false, "preview": false, "summary": "Knuth'un Turing Ödülü konuşması: programlama hem bilim hem sanattır ve iyi bir program estetik bir haz verir. Zarif, okunabilir kod yazmanın neden ciddiye alınması gereken bir değer olduğunu anlatan klasik metin.", "star": true}, {"id": "kay-early-history-smalltalk", "title": "The Early History of Smalltalk", "author": "Alan C. Kay", "date": "1993", "cat": "Teknik makale", "type": "makale", "url": "https://worrydream.com/EarlyHistoryOfSmalltalk/", "pdf": false, "preview": false, "summary": "Nesne yönelimli programlamanın, grafik arayüzün ve Dynabook fikrinin Xerox PARC'ta nasıl doğduğunu bizzat Kay'in anlatımıyla aktarıyor. Asıl fikir: nesneler birbirine mesaj gönderen küçük bilgisayarlar gibi düşünülmeli.", "star": true}, {"id": "unix-time-sharing-system", "title": "The UNIX Time-Sharing System", "author": "Dennis M. Ritchie & Ken Thompson", "date": "1974-07", "cat": "Teknik makale", "type": "makale", "url": "https://dsf.berkeley.edu/cs262/unix.pdf", "pdf": true, "preview": true, "summary": "UNIX'i dünyaya tanıtan makale: hiyerarşik dosya sistemi, her şeyin dosya olması, süreçler ve kabuk. Küçük, birleştirilebilir araçlar felsefesi bugünkü Linux, macOS ve Android'in temelinde yatıyor.", "star": true}, {"id": "cerf-kahn-tcp", "title": "A Protocol for Packet Network Intercommunication", "author": "Vinton G. Cerf & Robert E. Kahn", "date": "1974-05", "cat": "Teknik makale", "type": "makale", "url": "https://www.cs.princeton.edu/courses/archive/fall06/cos561/papers/cerf74.pdf", "pdf": true, "preview": true, "summary": "Birbirinden farklı paket ağlarını ortak bir protokol ve ağ geçitleriyle birbirine bağlamayı öneriyor. TCP/IP'nin ve dolayısıyla İnternet'in 'ağların ağı' tasarımının doğduğu makale.", "star": true}, {"id": "diffie-hellman-new-directions", "title": "New Directions in Cryptography", "author": "Whitfield Diffie & Martin E. Hellman", "date": "1976-11", "cat": "Teknik makale", "type": "makale", "url": "https://ee.stanford.edu/~hellman/publications/24.pdf", "pdf": true, "preview": false, "summary": "Önceden gizli anahtar paylaşmadan, açık bir kanal üzerinden güvenli anahtar anlaşması yapmanın yolunu gösteriyor ve açık anahtarlı şifreleme kavramını ortaya atıyor. HTTPS'ten kripto paralara kadar modern güvenliğin başlangıç noktası.", "star": true}, {"id": "rsa-public-key", "title": "A Method for Obtaining Digital Signatures and Public-Key Cryptosystems", "author": "Ronald L. Rivest, Adi Shamir & Leonard Adleman", "date": "1978-02", "cat": "Teknik makale", "type": "makale", "url": "https://people.csail.mit.edu/rivest/Rsapaper.pdf", "pdf": true, "preview": true, "summary": "Büyük sayıları çarpanlarına ayırmanın zorluğuna dayanan ilk pratik açık anahtarlı şifreleme ve dijital imza sistemi RSA'yı tanımlıyor. Diffie–Hellman'ın fikrini çalışan bir sisteme dönüştürdü.", "star": true}, {"id": "paxos-made-simple", "title": "Paxos Made Simple", "author": "Leslie Lamport", "date": "2001-11", "cat": "Teknik makale", "type": "makale", "url": "https://lamport.azurewebsites.net/pubs/paxos-simple.pdf", "pdf": true, "preview": true, "summary": "Bazı makineler çökse bile bir grup sunucunun tek bir değer üzerinde nasıl güvenle uzlaşacağını sade bir dille anlatıyor. Google'dan bulut veritabanlarına kadar dağıtık sistemlerdeki uzlaşma algoritmalarının temeli.", "star": true}, {"id": "kreps-the-log", "title": "The Log: What Every Software Engineer Should Know About Real-Time Data's Unifying Abstraction", "author": "Jay Kreps", "date": "2013-12", "cat": "Teknik makale", "type": "deneme", "url": "https://web.archive.org/web/20240105095933/https://engineering.linkedin.com/distributed-systems/log-what-every-software-engineer-should-know-about-real-time-datas-unifying", "pdf": false, "preview": false, "summary": "Sadece sona ekleme yapılan, sıralı bir olay kaydının (log) veritabanlarını, replikasyonu ve veri entegrasyonunu birleştiren temel soyutlama olduğunu savunuyor. Kafka'nın ve olay akışı mimarilerinin düşünsel manifestosu.", "star": true}, {"id": "out-of-the-tar-pit", "title": "Out of the Tar Pit", "author": "Ben Moseley & Peter Marks", "date": "2006-02", "cat": "Teknik makale", "type": "makale", "url": "https://curtclifton.net/papers/MoseleyMarks06a.pdf", "pdf": true, "preview": true, "summary": "Yazılımdaki asıl düşmanın karmaşıklık olduğunu, bunun da büyük ölçüde değişken durum ve kontrol akışından geldiğini savunuyor. Problemin özünden gelen karmaşıklığı kazara eklenenden ayırmayı ve ilişkisel/fonksiyonel bir tasarımı öneriyor.", "star": true}, {"id": "alphago-zero", "title": "Mastering the Game of Go without Human Knowledge (AlphaGo Zero)", "author": "David Silver et al. (DeepMind)", "date": "2017-10", "cat": "Yapay zekâ", "type": "makale", "url": "https://discovery.ucl.ac.uk/id/eprint/10045895/1/agz_unformatted_nature.pdf", "pdf": true, "preview": true, "summary": "Hiç insan oyunu görmeden, yalnızca kendine karşı oynayarak öğrenen bir sistemin Go'da insan verisiyle eğitilmiş AlphaGo'yu geçtiğini gösteriyor. Kendi kendine oynama ve pekiştirmeli öğrenmenin insan bilgisini aşabileceğinin çarpıcı kanıtı.", "star": true}, {"id": "alphafold-2", "title": "Highly Accurate Protein Structure Prediction with AlphaFold", "author": "John Jumper et al. (DeepMind)", "date": "2021-07", "cat": "Yapay zekâ", "type": "makale", "url": "https://www.nature.com/articles/s41586-021-03819-2", "pdf": false, "preview": false, "summary": "Proteinin üç boyutlu yapısını amino asit dizisinden deneysel ölçümlere yakın doğrulukla tahmin eden yapay zekâ sistemi. Biyolojide elli yıllık bir problemi büyük ölçüde çözdü ve 2024 Nobel Kimya Ödülü'ne konu oldu.", "star": true}, {"id": "gpt-2", "title": "Language Models are Unsupervised Multitask Learners (GPT-2)", "author": "Alec Radford et al. (OpenAI)", "date": "2019-02", "cat": "Yapay zekâ", "type": "makale", "url": "https://cdn.openai.com/better-language-models/language_models_are_unsupervised_multitask_learners.pdf", "pdf": true, "preview": true, "summary": "Yalnızca bir sonraki kelimeyi tahmin etmek üzere büyük metinlerle eğitilen bir modelin, özel eğitim almadan çeviri, özetleme ve soru cevaplama yapabildiğini gösteriyor. 'Ölçek büyüdükçe genel yetenekler kendiliğinden çıkar' fikrinin dönüm noktası.", "star": true}, {"id": "constitutional-ai", "title": "Constitutional AI: Harmlessness from AI Feedback", "author": "Yuntao Bai et al. (Anthropic)", "date": "2022-12", "cat": "Yapay zekâ", "type": "makale", "url": "https://arxiv.org/pdf/2212.08073", "pdf": true, "preview": true, "summary": "Bir yapay zekâyı, insan etiketleri yerine yazılı bir ilkeler listesine ('anayasa') göre kendi yanıtlarını eleştirip düzelterek hizalamayı öneriyor. Model davranışını açık, okunabilir kurallarla yönlendirmenin ölçeklenebilir bir yolu.", "star": true}, {"id": "einstein-electrodynamics-1905", "title": "On the Electrodynamics of Moving Bodies", "author": "Albert Einstein", "date": "1905-06", "cat": "Teknik makale", "type": "makale", "url": "https://www.fourmilab.ch/etexts/einstein/specrel/specrel.pdf", "pdf": true, "preview": true, "summary": "Işık hızının herkes için aynı olduğu ve fizik yasalarının tüm eylemsiz gözlemciler için geçerli olduğu iki varsayımdan özel görelilik kuramını türetiyor. Zaman ve uzayın mutlak olmadığını gösteren makalenin İngilizce çevirisi.", "star": true}, {"id": "watson-crick-dna-1953", "title": "Molecular Structure of Nucleic Acids: A Structure for Deoxyribose Nucleic Acid", "author": "James D. Watson & Francis H. C. Crick", "date": "1953-04", "cat": "Teknik makale", "type": "makale", "url": "https://dosequis.colorado.edu/Courses/MethodsLogic/papers/WatsonCrick1953.pdf", "pdf": true, "preview": true, "summary": "DNA'nın çift sarmal yapısını tek sayfalık bir mektupla öneriyor. Baz eşleşmesinin genetik bilginin kopyalanma mekanizmasına işaret ettiğini ima eden ünlü cümleyle moleküler biyolojiyi başlattı.", "star": true}, {"id": "mendel-plant-hybrids", "title": "Experiments on Plant Hybrids (Versuche über Pflanzen-Hybriden)", "author": "Gregor Mendel (çev. Abbott & Fairbanks)", "date": "1866", "cat": "Teknik makale", "type": "makale", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC5068836/", "pdf": false, "preview": false, "summary": "Bezelyelerle yapılan sistematik çaprazlamalardan özelliklerin karışarak değil, ayrık birimler halinde ve sayısal oranlarla kalıtıldığını çıkarıyor. Genetiğin kurucu metni; GENETICS dergisinin yeni İngilizce çevirisi.", "star": true}, {"id": "platt-strong-inference", "title": "Strong Inference", "author": "John R. Platt", "date": "1964-10", "cat": "Dünya görüşü", "type": "makale", "url": "https://pages.cs.wisc.edu/~markhill/science64_strong_inference.pdf", "pdf": true, "preview": true, "summary": "Bazı bilim alanlarının diğerlerinden çok daha hızlı ilerlemesini bir yönteme bağlıyor: alternatif hipotezler kur, aralarından eleyecek kesin deneyi tasarla, uygula, tekrarla. Her problem çözücü için düşünme disiplini.", "star": true}, {"id": "ioannidis-most-findings-false", "title": "Why Most Published Research Findings Are False", "author": "John P. A. Ioannidis", "date": "2005-08", "cat": "Dünya görüşü", "type": "deneme", "url": "https://journals.plos.org/plosmedicine/article/file?id=10.1371/journal.pmed.0020124&type=printable", "pdf": true, "preview": false, "summary": "Küçük örneklemler, küçük etki büyüklükleri, esnek analizler ve önyargı bir araya gelince yayımlanan bulguların çoğunun yanlış olmasının beklenebileceğini olasılık hesabıyla gösteriyor. Tekrarlanabilirlik krizinin ve 'bir çalışmaya körü körüne güvenme' tavrının kilit metni.", "star": true}, {"id": "hilbert-mathematical-problems", "title": "Mathematical Problems", "author": "David Hilbert", "date": "1900-08", "cat": "Teknik makale", "type": "konuşma", "url": "https://mathcs.clarku.edu/~djoyce/hilbert/problems.html", "pdf": false, "preview": false, "summary": "1900 Paris Uluslararası Matematikçiler Kongresi'nde sunulan ve yeni yüzyılın gündemini belirleyen açık problemler listesi. Doğru soruları sormanın bir alanı nasıl yönlendirebileceğinin en güçlü örneği.", "star": true}, {"id": "joy-future-doesnt-need-us", "title": "Why the Future Doesn't Need Us", "author": "Bill Joy", "date": "2000-04", "cat": "Dünya görüşü", "type": "deneme", "url": "https://www.wired.com/2000/04/joy-2/", "pdf": false, "preview": false, "summary": "Sun Microsystems'in kurucu ortağı, robotik, genetik mühendisliği ve nanoteknolojinin kendini kopyalayabilen, kontrolden çıkabilecek güçler yarattığını savunuyor. Teknoloji içinden gelen ilk büyük varoluşsal risk uyarılarından biri.", "star": true}, {"id": "good-ultraintelligent-machine", "title": "Speculations Concerning the First Ultraintelligent Machine", "author": "I. J. Good", "date": "1965", "cat": "Yapay zekâ", "type": "makale", "url": "http://incompleteideas.net/papers/Good65ultraintelligent.pdf", "pdf": true, "preview": false, "summary": "İnsandan zeki bir makinenin daha da zeki makineler tasarlayabileceğini ve bunun bir 'zekâ patlamasına' yol açacağını öne sürüyor. İlk ultra-zeki makinenin insanlığın yapması gereken son icat olacağı fikrinin kaynağı.", "star": true}, {"id": "anderson-more-is-different", "title": "More Is Different", "author": "Philip W. Anderson", "date": "1972-08", "cat": "Dünya görüşü", "type": "deneme", "url": "https://www.tkm.kit.edu/downloads/TKM1_2011_more_is_different_PWA.pdf", "pdf": true, "preview": false, "summary": "Bir sistemi parçalarına indirgeyebilmenin onu parçalardan yeniden kurabilmek anlamına gelmediğini savunuyor. Her karmaşıklık düzeyinde yeni yasalar ortaya çıkar; 'emergence' (ortaya çıkış) düşüncesinin manifestosu.", "star": true}, {"id": "dobzhansky-light-of-evolution", "title": "Nothing in Biology Makes Sense Except in the Light of Evolution", "author": "Theodosius Dobzhansky", "date": "1973-03", "cat": "Dünya görüşü", "type": "deneme", "url": "https://www.rpgroup.caltech.edu/marseillePBoC2024/assets/pdfs/nothing_sense.pdf", "pdf": true, "preview": true, "summary": "Canlılığın çeşitliliğinden moleküler benzerliklere kadar biyolojideki dağınık gerçeklerin ancak evrim ışığında anlamlı bir bütün oluşturduğunu savunuyor. Bir alanın tüm verisini tek bir birleştirici fikirle okumanın klasik örneği.", "star": true}, {"id": "simon-architecture-of-complexity", "title": "The Architecture of Complexity", "author": "Herbert A. Simon", "date": "1962-12", "cat": "Teknik makale", "type": "makale", "url": "https://faculty.sites.iastate.edu/tesfatsi/archive/tesfatsi/ArchitectureOfComplexity.HSimon1962.pdf", "pdf": true, "preview": true, "summary": "Karmaşık sistemlerin genellikle hiyerarşik ve 'neredeyse ayrıştırılabilir' modüllerden oluştuğunu, çünkü kararlı ara parçalardan kurulan sistemlerin çok daha hızlı evrildiğini gösteriyor. Saatçi benzetmesiyle modüler tasarımın neden kazandığını açıklayan temel metin.", "star": true}, {"id": "feynman-simulating-physics", "title": "Simulating Physics with Computers", "author": "Richard P. Feynman", "date": "1982", "cat": "Teknik makale", "type": "konuşma", "url": "https://s2.smu.edu/~mitch/class/5395/papers/feynman-quantum-1981.pdf", "pdf": true, "preview": true, "summary": "Kuantum sistemlerini klasik bilgisayarlarla verimli biçimde simüle etmenin üstel olarak zor olduğunu, doğayı simüle etmek için kuantum mekaniğiyle çalışan bir bilgisayar gerektiğini savunuyor. Kuantum bilgisayar fikrinin doğum belgesi.", "star": true}, {"id": "shor-quantum-factoring", "title": "Polynomial-Time Algorithms for Prime Factorization and Discrete Logarithms on a Quantum Computer", "author": "Peter W. Shor", "date": "1994", "cat": "Teknik makale", "type": "makale", "url": "https://arxiv.org/pdf/quant-ph/9508027", "pdf": true, "preview": true, "summary": "Bir kuantum bilgisayarın büyük sayıları çarpanlarına ayırma ve ayrık logaritma problemlerini verimli çözebileceğini gösteriyor. RSA gibi şifrelemeleri tehdit ettiği için kuantum hesaplamayı akademik meraktan stratejik bir yarışa dönüştürdü.", "star": true}, {"id": "cook-np-completeness", "title": "The Complexity of Theorem-Proving Procedures", "author": "Stephen A. Cook", "date": "1971", "cat": "Teknik makale", "type": "makale", "url": "https://www.cs.toronto.edu/~sacook/homepage/1971.pdf", "pdf": true, "preview": true, "summary": "Doğrulaması kolay ama çözümü zor görünen problemler sınıfında bazılarının 'en zor' olduğunu (NP-tamlık) gösteriyor. Bilgisayar biliminin en büyük açık sorusu P ile NP'nin eşit olup olmadığı burada biçimlendi.", "star": true}, {"id": "breiman-two-cultures", "title": "Statistical Modeling: The Two Cultures", "author": "Leo Breiman", "date": "2001", "cat": "Teknik makale", "type": "makale", "url": "https://www.stat.cmu.edu/~ryantibs/journalclub/breiman_2001.pdf", "pdf": true, "preview": true, "summary": "Veriyi varsayılan bir olasılık modeliyle açıklamaya çalışan klasik istatistik ile mekanizmayı kara kutu sayıp tahmin doğruluğunu ölçen algoritmik kültürü karşılaştırıyor. Makine öğrenmesinin istatistik içinde meşruiyet kazanmasında dönüm noktası.", "star": true}, {"id": "axelrod-evolution-of-cooperation", "title": "The Evolution of Cooperation", "author": "Robert Axelrod", "date": "1984", "cat": "Dünya görüşü", "type": "deneme", "url": "https://ee.stanford.edu/~hellman/Breakthrough/book/pdfs/axelrod.pdf", "pdf": true, "preview": false, "summary": "Tekrarlanan mahkûm ikilemi turnuvalarında en başarılı stratejinin basit 'kısasa kısas' (önce iş birliği, sonra karşı tarafın son hamlesini tekrarla) olduğunu gösteriyor. Merkezi otorite olmadan bencil aktörler arasında iş birliğinin nasıl doğduğunu açıklayan kitabın özet bölümü.", "star": true}, {"id": "darwin-origin-of-species", "title": "On the Origin of Species", "author": "Charles Darwin", "date": "1859-11", "cat": "Teknik makale", "type": "kitap", "url": "https://darwin-online.org.uk/converted/pdf/1859_Origin_F373.pdf", "pdf": true, "preview": false, "summary": "Türlerin doğal seçilim yoluyla, ortak atalardan kademeli olarak değiştiğini çok sayıda gözlemle savunan kitabın ilk baskısı. Biyolojinin ve insanın doğadaki yerine bakışın tamamen değiştiği metin.", "star": true}, {"id": "rip-good-times", "title": "RIP Good Times", "author": "Sequoia Capital", "date": "2008-10", "cat": "Girişim ve VC", "type": "sunum", "url": "https://www.sequoiacap.com/article/rip-good-times/", "pdf": false, "preview": false, "summary": "Sequoia'nın 2008 krizinde portföy şirketlerine sunduğu uyarı: nakdi koru, harcamayı kıs, kriz uzun sürecek."}, {"id": "how-to-get-startup-ideas", "title": "How to Get Startup Ideas", "author": "Paul Graham", "date": "2012-11", "cat": "Girişim ve VC", "type": "deneme", "url": "https://paulgraham.com/startupideas.html", "pdf": false, "preview": false, "summary": "İyi girişim fikirleri uydurulmaz; kendi yaşadığın sorunlarda fark edilir."}, {"id": "all-markets-not-created-equal", "title": "All Markets Are Not Created Equal", "author": "Bill Gurley", "date": "2012-11", "cat": "Girişim ve VC", "type": "deneme", "url": "https://abovethecrowd.com/2012/11/13/all-markets-are-not-created-equal-10-factors-to-consider-when-evaluating-digital-marketplaces/", "pdf": false, "preview": false, "summary": "Bir pazarın çekiciliğini belirleyen on faktör ve pazar büyüklüğü tahminlerine neden şüpheyle bakılması gerektiği."}, {"id": "next-big-thing-toy", "title": "The Next Big Thing Will Start Out Looking Like a Toy", "author": "Chris Dixon", "date": "2010-01", "cat": "Girişim ve VC", "type": "deneme", "url": "https://cdixon.org/2010/01/03/the-next-big-thing-will-start-out-looking-like-a-toy", "pdf": false, "preview": false, "summary": "Devrim yaratan teknolojiler önce oyuncak gibi görünür, bu yüzden hafife alınır."}, {"id": "why-decentralization-matters", "title": "Why Decentralization Matters", "author": "Chris Dixon", "date": "2018-02", "cat": "Girişim ve VC", "type": "deneme", "url": "https://onezero.medium.com/why-decentralization-matters-5e3f79f7638e", "pdf": false, "preview": false, "summary": "Merkezi platformların zamanla kullanıcıya karşı döndüğü, merkeziyetsiz ağların bu döngüyü kırabileceği savı."}, {"id": "invisible-asymptotes", "title": "Invisible Asymptotes", "author": "Eugene Wei", "date": "2018-05", "cat": "Girişim ve VC", "type": "deneme", "url": "https://www.eugenewei.com/blog/2018/5/21/invisible-asymptotes", "pdf": false, "preview": false, "summary": "Her büyüme eğrisinin önünde görünmez bir tavan vardır; onu erken fark etmek strateji işidir."}, {"id": "what-happened-to-the-future", "title": "What Happened to the Future?", "author": "Founders Fund (Bruce Gibney)", "date": "2011", "cat": "Girişim ve VC", "type": "manifesto", "url": "https://foundersfund.com/the-future/", "pdf": false, "preview": false, "summary": "Founders Fund manifestosu: “Uçan arabalar istedik, 140 karakter aldık”; büyük teknolojik hedeflere dönüş çağrısı."}, {"id": "ethereum-whitepaper", "title": "Ethereum Whitepaper: A Next-Generation Smart Contract Platform", "author": "Vitalik Buterin", "date": "2013-12", "cat": "Teknik makale", "type": "teknik doküman", "url": "https://ethereum.org/en/whitepaper/", "pdf": false, "preview": false, "summary": "Blokzincir üzerinde her türlü programı çalıştırabilen genel amaçlı akıllı sözleşme platformu."}, {"id": "alexnet", "title": "ImageNet Classification with Deep Convolutional Neural Networks (AlexNet)", "author": "Krizhevsky, Sutskever, Hinton", "date": "2012", "cat": "Teknik makale", "type": "makale", "url": "https://papers.nips.cc/paper/2012/hash/c399862d3b9d6b76c8436e924a68c45b-Abstract.html", "pdf": false, "preview": false, "summary": "Derin evrişimli bir ağın ImageNet'te büyük farkla kazanması ve derin öğrenme çağının başlangıcı."}, {"id": "gpt-3", "title": "Language Models are Few-Shot Learners (GPT-3)", "author": "Brown et al. (OpenAI)", "date": "2020-05", "cat": "Teknik makale", "type": "makale", "url": "https://arxiv.org/abs/2005.14165", "pdf": false, "preview": false, "summary": "Yeterince büyük bir dil modelinin, birkaç örnekle yeni görevleri öğrenebildiğini gösteren makale."}, {"id": "scaling-laws", "title": "Scaling Laws for Neural Language Models", "author": "Kaplan et al. (OpenAI)", "date": "2020-01", "cat": "Teknik makale", "type": "makale", "url": "https://arxiv.org/abs/2001.08361", "pdf": false, "preview": false, "summary": "Dil modeli başarısının model boyutu, veri ve hesaplamayla öngörülebilir biçimde arttığını gösteren yasalar."}, {"id": "chinchilla", "title": "Training Compute-Optimal Large Language Models (Chinchilla)", "author": "Hoffmann et al. (DeepMind)", "date": "2022-03", "cat": "Teknik makale", "type": "makale", "url": "https://arxiv.org/abs/2203.15556", "pdf": false, "preview": false, "summary": "Aynı hesaplama bütçesinde daha küçük model ve daha çok veriyle daha iyi sonuç alınabileceği bulgusu."}, {"id": "deepseek-r1", "title": "DeepSeek-R1: Incentivizing Reasoning Capability via RL", "author": "DeepSeek", "date": "2025-01", "cat": "Teknik makale", "type": "makale", "url": "https://arxiv.org/abs/2501.12948", "pdf": false, "preview": false, "summary": "Pekiştirmeli öğrenmeyle dil modellerinde akıl yürütme yeteneğinin geliştirilmesi."}, {"id": "software-2-0", "title": "Software 2.0", "author": "Andrej Karpathy", "date": "2017-11", "cat": "Yapay zekâ", "type": "deneme", "url": "https://karpathy.medium.com/software-2-0-a64152b37c35", "pdf": false, "preview": false, "summary": "Yazılımın giderek elle yazılan kod yerine veriden öğrenilen sinir ağı ağırlıklarına dönüşmesi."}, {"id": "situational-awareness", "title": "Situational Awareness: The Decade Ahead", "author": "Leopold Aschenbrenner", "date": "2024-06", "cat": "Yapay zekâ", "type": "deneme", "url": "https://situational-awareness.ai/", "pdf": false, "preview": false, "summary": "Önümüzdeki on yılda genel yapay zekâya hızla ulaşılabileceğini ve bunun jeopolitik sonuçlarını tartışan uzun deneme."}, {"id": "machines-of-loving-grace", "title": "Machines of Loving Grace", "author": "Dario Amodei", "date": "2024-10", "cat": "Yapay zekâ", "type": "deneme", "url": "https://www.darioamodei.com/essay/machines-of-loving-grace", "pdf": false, "preview": false, "summary": "Güçlü yapay zekânın biyoloji, sağlık ve ekonomide neleri iyileştirebileceğine dair iyimser bir vizyon."}, {"id": "marks-sea-change", "title": "Sea Change", "author": "Howard Marks", "date": "2022-12", "cat": "Makro ve yatırım", "type": "not", "url": "https://www.oaktreecapital.com/insights/memo/sea-change", "pdf": false, "preview": false, "summary": "Faizlerin sıfırdan yükselmesiyle yatırım ortamında köklü bir dönüşüm başladığı görüşü."}, {"id": "marks-race-to-bottom", "title": "The Race to the Bottom", "author": "Howard Marks", "date": "2007-02", "cat": "Makro ve yatırım", "type": "not", "url": "https://www.oaktreecapital.com/insights/memo/the-race-to-the-bottom", "pdf": false, "preview": false, "summary": "Bol para dönemlerinde yatırımcıların riskleri gözden kaçırıp standartlarını gevşetmesi üzerine."}, {"id": "pozsar-bretton-woods-iii", "title": "Bretton Woods III", "author": "Zoltan Pozsar", "date": "2022-03", "cat": "Makro ve yatırım", "type": "not", "url": "https://static.bullionstar.com/blogs/uploads/2022/03/Bretton-Woods-III-Zoltan-Pozsar.pdf", "pdf": true, "preview": true, "summary": "Yaptırımlar sonrası para sisteminin emtiaya dayalı yeni bir düzene kayabileceği tezi."}, {"id": "dalio-changing-world-order", "title": "The Changing World Order", "author": "Ray Dalio", "date": "2020", "cat": "Makro ve yatırım", "type": "deneme", "url": "https://asiabusinesscouncil.org/wp-content/uploads/2020/10/The-Changing-World-Order_Ray-Dalio.pdf", "pdf": true, "preview": true, "summary": "İmparatorlukların ve rezerv paraların yükseliş ve düşüş döngülerini inceleyen tarihsel analiz."}, {"id": "buffett-buy-american", "title": "Buy American. I Am.", "author": "Warren Buffett", "date": "2008-10", "cat": "Makro ve yatırım", "type": "köşe yazısı", "url": "https://www.nytimes.com/2008/10/17/opinion/17buffett.html", "pdf": false, "preview": false, "summary": "2008 krizinin ortasında Buffett'ın Amerikan hisselerine yatırım yaptığını açıkladığı köşe yazısı."}, {"id": "sovereign-individual", "title": "The Sovereign Individual", "author": "James Dale Davidson & Lord William Rees-Mogg", "date": "1997", "cat": "Dünya görüşü", "type": "kitap", "url": "https://en.wikipedia.org/wiki/The_Sovereign_Individual", "pdf": false, "preview": false, "summary": "Dijital teknolojinin ulus devletlerin gücünü zayıflatıp bireyi güçlendireceğini öngören kitap."}, {"id": "techno-optimist-manifesto", "title": "The Techno-Optimist Manifesto", "author": "Marc Andreessen", "date": "2023-10", "cat": "Dünya görüşü", "type": "manifesto", "url": "https://a16z.com/the-techno-optimist-manifesto/", "pdf": false, "preview": false, "summary": "Teknolojinin ve büyümenin insanlık için temel ilerleme kaynağı olduğunu savunan manifesto."}, {"id": "most-important-century", "title": "The Most Important Century", "author": "Holden Karnofsky", "date": "2021", "cat": "Dünya görüşü", "type": "deneme dizisi", "url": "https://www.cold-takes.com/most-important-century/", "pdf": false, "preview": false, "summary": "Yapay zekâ nedeniyle bu yüzyılın insanlık tarihinin en önemli dönemi olabileceğini tartışan deneme dizisi."}, {"id": "agi-ruin", "title": "AGI Ruin: A List of Lethalities", "author": "Eliezer Yudkowsky", "date": "2022-06", "cat": "Dünya görüşü", "type": "deneme", "url": "https://www.lesswrong.com/posts/uMQ3cqWDPHhjtiesc/agi-ruin-a-list-of-lethalities", "pdf": false, "preview": false, "summary": "Hizalanmamış genel yapay zekânın neden ölümcül olabileceğine dair maddeler hâlinde uyarılar."}, {"id": "zero-to-one", "title": "Zero to One", "author": "Peter Thiel & Blake Masters", "date": "2014", "cat": "Dünya görüşü", "type": "kitap", "url": "https://blakemasters.tumblr.com/peter-thiels-cs183-startup", "pdf": false, "preview": false, "summary": "Kopyalamak yerine yeni bir şey yaratmak ve tekel benzeri şirketler kurmak üzerine ders notları."}, {"id": "progress-studies", "title": "We Need a New Science of Progress", "author": "Patrick Collison & Tyler Cowen", "date": "2019-07", "cat": "Dünya görüşü", "type": "deneme", "url": "https://www.theatlantic.com/science/archive/2019/07/we-need-new-science-progress/594946/", "pdf": false, "preview": false, "summary": "İlerlemenin neden ve nasıl gerçekleştiğini inceleyecek yeni bir bilim dalı çağrısı."}, {"id": "scaling-hypothesis", "title": "The Scaling Hypothesis", "author": "Gwern Branwen", "date": "2020-05", "cat": "Dünya görüşü", "type": "deneme", "url": "https://gwern.net/scaling-hypothesis", "pdf": false, "preview": false, "summary": "Yalnızca ölçeği büyütmenin yapay zekâda yeni yetenekler doğurabileceği hipotezi."}, {"id": "fat-protocols", "title": "Fat Protocols", "author": "Joel Monegro / USV", "date": "2016-08", "cat": "Kripto", "type": "deneme", "url": "https://www.usv.com/writing/2016/08/fat-protocols/", "pdf": false, "preview": false, "summary": "Blokzincirde değerin uygulamalarda değil, alttaki protokol katmanında biriktiği tezi."}, {"id": "bullish-case-for-bitcoin", "title": "The Bullish Case for Bitcoin", "author": "Vijay Boyapati", "date": "2018-03", "cat": "Kripto", "type": "deneme", "url": "https://vijayboyapati.medium.com/the-bullish-case-for-bitcoin-6ecc8bdecc1", "pdf": false, "preview": false, "summary": "Bitcoin'in sağlam para özellikleri sayesinde değer saklama aracına dönüşeceği savı."}, {"id": "minimum-viable-product-ries", "title": "The Lean Startup / Minimum Viable Product", "author": "Eric Ries", "date": "2011", "cat": "Girişim ve VC", "type": "kitap", "url": "https://www.startuplessonslearned.com/2009/08/minimum-viable-product-guide.html", "pdf": false, "preview": false, "summary": "Minimum uygulanabilir ürünle (MVP) hızlı öğrenmeye ve ölçüme dayalı girişim yöntemi."}, {"id": "dalio-big-debt-crises", "title": "Principles for Navigating Big Debt Crises", "author": "Ray Dalio", "date": "2018", "cat": "Makro ve yatırım", "type": "kitap", "url": "https://www.principles.com/big-debt-crises/", "pdf": false, "preview": false, "summary": "Büyük borç krizlerinin nasıl oluştuğunu ve nasıl yönetildiğini anlatan tarihsel rehber."}, {"id": "grantham-reinvesting-when-terrified", "title": "Reinvesting When Terrified", "author": "Jeremy Grantham", "date": "2009-03", "cat": "Makro ve yatırım", "type": "not", "url": "https://www.gmo.com/americas/research-library/reinvesting-when-terrified/", "pdf": false, "preview": false, "summary": "Panik dönemlerinde yeniden yatırım yapmanın neden zor ama doğru olduğu üzerine not."}, {"id": "resnet", "title": "Deep Residual Learning for Image Recognition (ResNet)", "author": "He, Zhang, Ren, Sun (Microsoft)", "date": "2015-12", "cat": "Teknik makale", "type": "makale", "url": "https://arxiv.org/abs/1512.03385", "pdf": false, "preview": false, "summary": "Artık bağlantılarla çok derin sinir ağlarının eğitilebilmesini sağlayan ResNet mimarisi."}, {"id": "word2vec", "title": "Efficient Estimation of Word Representations (word2vec)", "author": "Mikolov et al. (Google)", "date": "2013-01", "cat": "Teknik makale", "type": "makale", "url": "https://arxiv.org/abs/1301.3781", "pdf": false, "preview": false, "summary": "Kelimeleri anlamlarını taşıyan vektörler olarak temsil eden verimli yöntem."}, {"id": "superintelligence-bostrom", "title": "Superintelligence: Paths, Dangers, Strategies", "author": "Nick Bostrom", "date": "2014", "cat": "Dünya görüşü", "type": "kitap", "url": "https://en.wikipedia.org/wiki/Superintelligence:_Paths,_Dangers,_Strategies", "pdf": false, "preview": false, "summary": "İnsanüstü yapay zekânın yolları, tehlikeleri ve kontrol stratejileri üzerine kitap."}, {"id": "internet-tidal-wave", "title": "The Internet Tidal Wave", "author": "Bill Gates", "date": "1995-05", "cat": "Dünya görüşü", "type": "not", "url": "http://news.bbc.co.uk/2/shared/bsp/hi/pdfs/18_06_08_internet%20tidal%20wave.pdf", "pdf": true, "preview": false, "summary": "Bill Gates'in 1995 notu: internet, Microsoft'un tüm stratejisini değiştirmesi gereken bir dalga."}, {"id": "increasing-returns", "title": "Increasing Returns and the New World of Business", "author": "W. Brian Arthur", "date": "1996-07", "cat": "Dünya görüşü", "type": "deneme", "url": "https://sites.santafe.edu/~wbarthur/Papers/HBR.pdf", "pdf": true, "preview": true, "summary": "Bilgi ekonomisinde kazananın daha çok kazandığı artan getiriler kavramı."}, {"id": "black-scholes", "title": "The Pricing of Options and Corporate Liabilities", "author": "Fischer Black, Myron Scholes", "date": "1973-05", "cat": "Teknik makale", "type": "makale", "url": "https://www.journals.uchicago.edu/doi/10.1086/260062", "pdf": false, "preview": false, "summary": "Opsiyon fiyatlamasının matematiksel formülünü veren ve finansı dönüştüren makale."}, {"id": "madoff-fraud-memo", "title": "The World's Largest Hedge Fund Is a Fraud", "author": "Harry Markopolos", "date": "2005-11", "cat": "Makro ve yatırım", "type": "rapor", "url": "https://www.sec.gov/news/studies/2009/oig-509/exhibit-0293.pdf", "pdf": true, "preview": false, "summary": "Madoff'un fonunun bir sahtekârlık olduğunu çöküşünden yıllar önce kanıtlamaya çalışan rapor."}, {"id": "tesla-master-plan", "title": "The Secret Tesla Motors Master Plan (just between you and me)", "author": "Elon Musk", "date": "2006-08", "cat": "Dünya görüşü", "type": "deneme", "url": "https://www.tesla.com/blog/secret-tesla-motors-master-plan-just-between-you-and-me", "pdf": false, "preview": false, "summary": "Pahalı spor arabayla başlayıp uygun fiyatlı elektrikli araca ulaşmayı planlayan ilk Tesla planı."}, {"id": "worse-is-better", "title": "The Rise of Worse is Better", "author": "Richard P. Gabriel", "date": "1989", "cat": "Teknik makale", "type": "deneme", "url": "https://www.dreamsongs.com/RiseOfWorseIsBetter.html", "pdf": false, "preview": false, "summary": "Basit ama kusurlu yazılımın, kusursuz ama karmaşık rakibine karşı neden yayılıp kazandığını anlatıyor. Önce yayıl, sonra iyileş stratejisinin klasik savunusu."}, {"id": "pg-how-to-do-great-work", "title": "How to Do Great Work", "author": "Paul Graham", "date": "2023-07", "cat": "Dünya görüşü", "type": "deneme", "url": "https://paulgraham.com/greatwork.html", "pdf": false, "preview": false, "summary": "Merakın, sıkı çalışmanın ve doğru alanı seçmenin nasıl birleşip olağanüstü işe dönüştüğünü anlatan uzun bir rehber. Neye ilgi duyduğunu ciddiye almanı ve sınırın en uç noktasında çalışmanı öneriyor."}, {"id": "pg-startup-equals-growth", "title": "Startup = Growth", "author": "Paul Graham", "date": "2012-09", "cat": "Girişim ve VC", "type": "deneme", "url": "https://paulgraham.com/growth.html", "pdf": false, "preview": false, "summary": "Startup'ı sıradan bir şirketten ayıran tek şeyin hızlı büyüme için tasarlanmış olması olduğunu savunuyor. Haftalık büyüme oranını pusula yapmanı öneriyor."}, {"id": "pg-makers-schedule", "title": "Maker's Schedule, Manager's Schedule", "author": "Paul Graham", "date": "2009-07", "cat": "Dünya görüşü", "type": "deneme", "url": "https://paulgraham.com/makersschedule.html", "pdf": false, "preview": false, "summary": "Yöneticiler günü bir saatlik dilimlerle, üretenler ise yarım günlük bloklarla yaşar; tek bir toplantı üreticinin tüm öğleden sonrasını öldürebilir. Takvimini korumak için basit ama güçlü bir çerçeve."}, {"id": "pg-founder-mode", "title": "Founder Mode", "author": "Paul Graham", "date": "2024-09", "cat": "Girişim ve VC", "type": "deneme", "url": "https://paulgraham.com/foundermode.html", "pdf": false, "preview": false, "summary": "Klasik 'iyi insanları işe al, onlara alan bırak' yönetim tavsiyesinin kurucular için neden ters tepebildiğini anlatıyor. Kurucunun şirketin derinliklerine dokunmaya devam ettiği ayrı bir yönetim modu öneriyor."}, {"id": "pg-how-to-make-wealth", "title": "How to Make Wealth", "author": "Paul Graham", "date": "2004-05", "cat": "Girişim ve VC", "type": "deneme", "url": "https://paulgraham.com/wealth.html", "pdf": false, "preview": false, "summary": "Zenginliğin paradan farklı olduğunu, insanların istediği şeyleri üreterek yaratıldığını savunuyor. Startup'ı, birkaç yıllık çalışmayı yoğunlaştırıp ölçülebilir ve kaldıraçlı hale getirmenin yolu olarak görüyor."}, {"id": "pg-beating-the-averages", "title": "Beating the Averages", "author": "Paul Graham", "date": "2001-04", "cat": "Teknik makale", "type": "deneme", "url": "https://www.paulgraham.com/avg.html", "pdf": false, "preview": false, "summary": "Viaweb'de Lisp kullanmanın rakiplere karşı nasıl gizli bir avantaj olduğunu anlatıyor ve 'Blub paradoksu'nu ortaya koyuyor: yalnızca bildiğin dille düşünürsen ondan daha güçlü dillerin değerini göremezsin."}, {"id": "pg-hackers-and-painters", "title": "Hackers and Painters", "author": "Paul Graham", "date": "2003-05", "cat": "Dünya görüşü", "type": "deneme", "url": "https://www.paulgraham.com/hs.html", "pdf": false, "preview": false, "summary": "Programlamayı mühendislikten çok ressamlık gibi bir yaratım işi olarak görüyor: eskiz yap, dene, düzelt. Yazılımcıyı bilim insanı değil, zanaatkâr olarak konumlandırıyor."}, {"id": "its-time-to-build", "title": "It's Time to Build", "author": "Marc Andreessen", "date": "2020-04", "cat": "Dünya görüşü", "type": "deneme", "url": "https://a16z.com/its-time-to-build/", "pdf": false, "preview": false, "summary": "Pandeminin ortaya çıkardığı hazırlıksızlığı, Batı'nın bir şeyler inşa etme isteğini kaybetmesine bağlıyor. Sorunun para ya da bilgi değil, irade eksikliği olduğunu söylüyor."}, {"id": "berkshire-owners-manual", "title": "An Owner's Manual", "author": "Warren Buffett", "date": "1996", "cat": "Makro ve yatırım", "type": "kılavuz", "url": "https://www.berkshirehathaway.com/ownman.pdf", "pdf": true, "preview": false, "summary": "Buffett, hissedarlarına şirketi nasıl yönettiğini anlatan ilkeleri sıralıyor: kendini ortak gör, içsel değere bak, borçtan kaçın. Uzun vadeli sermaye yönetiminin özeti."}, {"id": "buffett-1987-letter", "title": "Berkshire Hathaway Shareholder Letter 1987", "author": "Warren Buffett", "date": "1988-02", "cat": "Makro ve yatırım", "type": "mektup", "url": "https://www.berkshirehathaway.com/letters/1987.html", "pdf": false, "preview": false, "summary": "Graham'ın 'Bay Piyasa' benzetmesini anlatan ünlü mektup: piyasa sana her gün fiyat teklif eden duygusal bir ortaktır, ona hizmet etme, ondan yararlan. Krizleri fırsata çevirmenin zihinsel çerçevesi."}, {"id": "marks-dare-to-be-great-ii", "title": "Dare to Be Great II", "author": "Howard Marks", "date": "2014-04", "cat": "Makro ve yatırım", "type": "not", "url": "https://www.oaktreecapital.com/insights/memo/dare-to-be-great-ii", "pdf": false, "preview": false, "summary": "Ortalamanın üstünde getiri istiyorsan kalabalıktan farklı düşünmen ve haklı çıkman gerektiğini, bunun da yalnız kalmayı ve zaman zaman yanılmayı göze almayı gerektirdiğini anlatıyor."}, {"id": "bezos-2015-letter", "title": "2015 Letter to Shareholders", "author": "Jeff Bezos", "date": "2016-04", "cat": "Girişim ve VC", "type": "mektup", "url": "https://s2.q4cdn.com/299287126/files/doc_financials/annual/2015-Letter-to-Shareholders.PDF", "pdf": true, "preview": true, "summary": "Kararları geri döndürülebilir 'iki yönlü kapılar' ve geri dönüşü olmayan 'tek yönlü kapılar' olarak ayırıyor; büyük şirketlerin geri döndürülebilir kararları da tek yönlü kapı gibi yavaş ve ağır süreçlerle ele alarak hantallaştığını söylüyor. Başarısızlık ve icadın ayrılmaz olduğunu da vurguluyor."}, {"id": "bezos-2016-day-1-letter", "title": "2016 Letter to Shareholders (Day 1)", "author": "Jeff Bezos", "date": "2017-04", "cat": "Girişim ve VC", "type": "mektup", "url": "https://www.aboutamazon.com/news/company-news/2016-letter-to-shareholders", "pdf": false, "preview": false, "summary": "'2. Gün durgunluktur; ardından önemsizleşme, acı verici bir çöküş ve ölüm gelir.' Bir şirketi hep '1. Gün'de tutmak için müşteri takıntısı, vekil metriklere karşı şüphe, dış trendleri benimsemek ve hızlı karar almayı öneriyor."}, {"id": "valve-handbook", "title": "Valve Handbook for New Employees", "author": "Valve", "date": "2012", "cat": "Girişim ve VC", "type": "kılavuz", "url": "https://cdn.akamai.steamstatic.com/apps/valve/Valve_NewEmployeeHandbook.pdf", "pdf": true, "preview": true, "summary": "Yöneticisi olmayan, masaların tekerlekli olduğu ve herkesin ne üzerinde çalışacağını kendisinin seçtiği bir şirketin nasıl işlediğini anlatıyor. Düz organizasyon fikrinin en ünlü belgesi."}, {"id": "plenty-of-room-at-the-bottom", "title": "There's Plenty of Room at the Bottom", "author": "Richard Feynman", "date": "1960-02", "cat": "Teknik makale", "type": "konuşma", "url": "https://calteches.library.caltech.edu/1976/1/1960Bottom.pdf", "pdf": true, "preview": true, "summary": "Maddeyi atom düzeyinde düzenleyebilseydik neler yapabileceğimizi soruyor: bütün ansiklopediyi toplu iğne başına yazmak gibi. Nanoteknolojinin kurucu metni sayılıyor."}, {"id": "tyranny-of-structurelessness", "title": "The Tyranny of Structurelessness", "author": "Jo Freeman", "date": "1972", "cat": "Dünya görüşü", "type": "deneme", "url": "https://www.jofreeman.com/joreen/tyranny.htm", "pdf": false, "preview": false, "summary": "'Yapısız' grupların aslında yapısız olmadığını, resmi kurallar yokken gücün görünmez ve hesap vermeyen gayriresmi elitlere geçtiğini gösteriyor. Düz organizasyon kuran herkesin okuması gereken uyarı."}, {"id": "how-will-you-measure-your-life", "title": "How Will You Measure Your Life?", "author": "Clayton M. Christensen", "date": "2010-07", "cat": "Dünya görüşü", "type": "makale", "url": "https://hbr.org/2010/07/how-will-you-measure-your-life", "pdf": false, "preview": false, "summary": "Yönetim teorilerini kişisel hayata uyguluyor: zamanını ve enerjini kısa vadeli başarılara değil, aileye ve dürüstlüğe yatır. 'Sadece bu seferlik' istisnasının seni nasıl yoldan çıkardığını anlatıyor."}, {"id": "taleb-fourth-quadrant", "title": "The Fourth Quadrant: A Map of the Limits of Statistics", "author": "Nassim Nicholas Taleb", "date": "2008-09", "cat": "Makro ve yatırım", "type": "deneme", "url": "https://www.edge.org/conversation/nassim_nicholas_taleb-the-fourth-quadrant-a-map-of-the-limits-of-statistics", "pdf": false, "preview": false, "summary": "Karmaşık getirilerin kalın kuyruklu dağılımlarla buluştuğu 'dördüncü çeyrekte' istatistiksel modellerin neden işe yaramadığını haritalıyor. Bu bölgede tahmin yerine dayanıklılığa yatırım yapmanı öneriyor."}, {"id": "altman-how-to-be-successful", "title": "How To Be Successful", "author": "Sam Altman", "date": "2019-01", "cat": "Girişim ve VC", "type": "deneme", "url": "https://blog.samaltman.com/how-to-be-successful", "pdf": false, "preview": false, "summary": "Kendini bileşik faiz gibi büyüt, neredeyse aşırı özgüvenli ol, bağımsız düşün, risk almaktan korkma: Altman'ın binlerce kurucuyu izleyerek çıkardığı 13 ilke."}, {"id": "man-computer-symbiosis", "title": "Man-Computer Symbiosis", "author": "J. C. R. Licklider", "date": "1960-03", "cat": "Teknik makale", "type": "makale", "url": "https://groups.csail.mit.edu/medg/people/psz/Licklider.html", "pdf": false, "preview": false, "summary": "Bilgisayarı insanın yerini alan bir makine değil, düşünme sürecinde ortak çalışan bir partner olarak hayal ediyor. Etkileşimli bilgisayarın ve internetin entelektüel kökü."}, {"id": "augmenting-human-intellect", "title": "Augmenting Human Intellect: A Conceptual Framework", "author": "Douglas C. Engelbart", "date": "1962-10", "cat": "Teknik makale", "type": "rapor", "url": "https://www.dougengelbart.org/pubs/augment-3906.html", "pdf": false, "preview": false, "summary": "Teknolojinin amacının insanın karmaşık problemleri anlama ve çözme kapasitesini büyütmek olduğunu savunuyor. Fareye, hiper metne ve ortak çalışma araçlarına uzanan yolun ilk haritası."}, {"id": "ostrom-beyond-markets-and-states", "title": "Beyond Markets and States: Polycentric Governance of Complex Economic Systems", "author": "Elinor Ostrom", "date": "2009-12", "cat": "Makro ve yatırım", "type": "konuşma", "url": "https://www.nobelprize.org/uploads/2018/06/ostrom_lecture.pdf", "pdf": true, "preview": true, "summary": "Ortak kaynakların ille de devlet ya da piyasa tarafından yönetilmesi gerekmediğini, toplulukların kendi kurallarını koyarak onları sürdürebildiğini gösteren Nobel konuşması. Hardin'in 'trajedisine' sahadan gelen cevap."}, {"id": "hayek-pretence-of-knowledge", "title": "The Pretence of Knowledge", "author": "Friedrich A. von Hayek", "date": "1974-12", "cat": "Makro ve yatırım", "type": "konuşma", "url": "https://www.nobelprize.org/prizes/economic-sciences/1974/hayek/lecture/", "pdf": false, "preview": false, "summary": "İktisatçıların karmaşık sistemleri fizik kesinliğiyle ölçebileceklerini sanmasının tehlikesini anlatan Nobel konuşması. Bilmediğini bilmenin, yanlış kesinlikten daha değerli olduğunu savunuyor."}, {"id": "goto-considered-harmful", "title": "Go To Statement Considered Harmful", "author": "Edsger W. Dijkstra", "date": "1968-03", "cat": "Teknik makale", "type": "mektup", "url": "https://homepages.cwi.nl/~storm/teaching/reader/Dijkstra68.pdf", "pdf": true, "preview": true, "summary": "Kontrolsüz atlama komutlarının programı okunmaz kıldığını ve yapısal programlamaya geçilmesi gerektiğini savunan kısa mektup. 'X zararlı sayılır' kalıbının da kaynağı."}, {"id": "the-humble-programmer", "title": "The Humble Programmer", "author": "Edsger W. Dijkstra", "date": "1972", "cat": "Teknik makale", "type": "konuşma", "url": "https://www.cs.utexas.edu/~EWD/ewd03xx/EWD340.PDF", "pdf": true, "preview": false, "summary": "Turing Ödülü konuşmasında programcılığın zorluğunun insan zihninin sınırlı kapasitesinden geldiğini, bu yüzden alçakgönüllü ve basitliğe takıntılı olmak gerektiğini anlatıyor."}, {"id": "trusting-trust", "title": "Reflections on Trusting Trust", "author": "Ken Thompson", "date": "1984-08", "cat": "Teknik makale", "type": "konuşma", "url": "https://www.cs.cmu.edu/~rdriley/487/papers/Thompson_1984_ReflectionsonTrustingTrust.pdf", "pdf": true, "preview": true, "summary": "Derleyiciye gizlenen bir arka kapının kaynak kodda hiç iz bırakmadan kendini çoğaltabileceğini gösteriyor. Sonuç: kendin yazmadığın koda tam olarak güvenemezsin."}, {"id": "conways-law", "title": "How Do Committees Invent?", "author": "Melvin E. Conway", "date": "1968-04", "cat": "Teknik makale", "type": "makale", "url": "https://www.melconway.com/Home/pdf/committees.pdf", "pdf": true, "preview": true, "summary": "Bir sistemi tasarlayan organizasyonun, kaçınılmaz olarak kendi iletişim yapısının kopyası olan bir tasarım üreteceğini savunuyor: Conway Yasası. Ekip yapısını değiştirmeden mimariyi değiştiremezsin."}, {"id": "cathedral-and-the-bazaar", "title": "The Cathedral and the Bazaar", "author": "Eric S. Raymond", "date": "1997", "cat": "Teknik makale", "type": "deneme", "url": "http://www.catb.org/~esr/writings/cathedral-bazaar/cathedral-bazaar/", "pdf": false, "preview": false, "summary": "Yazılımı kapalı bir ekibin katedral gibi inşa etmesi ile herkese açık bir pazar yeri gibi geliştirilmesini karşılaştırıyor. 'Yeterince göz varsa her hata sığdır' ilkesiyle açık kaynağın manifestosu."}, {"id": "joel-things-you-should-never-do", "title": "Things You Should Never Do, Part I", "author": "Joel Spolsky", "date": "2000-04", "cat": "Teknik makale", "type": "deneme", "url": "https://www.joelonsoftware.com/2000/04/06/things-you-should-never-do-part-i/", "pdf": false, "preview": false, "summary": "Çalışan bir kodu sıfırdan yeniden yazmanın bir yazılım şirketinin yapabileceği en büyük stratejik hata olduğunu savunuyor. Eski kodun içindeki çirkinlik, aslında yıllarca düzeltilmiş hataların birikimidir."}, {"id": "horowitz-peacetime-wartime-ceo", "title": "Peacetime CEO/Wartime CEO", "author": "Ben Horowitz", "date": "2011-04", "cat": "Girişim ve VC", "type": "deneme", "url": "https://a16z.com/peacetime-ceo-wartime-ceo/", "pdf": false, "preview": false, "summary": "Şirket büyürken işe yarayan uzlaşmacı liderliğin, varoluşsal tehdit anında nasıl bir yüke dönüştüğünü anlatıyor. Hangi moddaysan ona göre davranmanı öneriyor."}, {"id": "horowitz-good-pm-bad-pm", "title": "Good Product Manager/Bad Product Manager", "author": "Ben Horowitz & David Weiden", "date": "1996", "cat": "Girişim ve VC", "type": "not", "url": "https://a16z.com/good-product-manager-bad-product-manager/", "pdf": false, "preview": false, "summary": "Netscape'te yazılmış, iyi ürün yöneticisini kötüsünden ayıran davranışları karşılaştırmalı listeleyen kısa eğitim notu. Ürün yöneticisinin 'ürünün CEO'su' olduğu fikrini yaygınlaştıran metin."}, {"id": "shelling-out", "title": "Shelling Out: The Origins of Money", "author": "Nick Szabo", "date": "2002", "cat": "Kripto", "type": "deneme", "url": "https://nakamotoinstitute.org/library/shelling-out/", "pdf": false, "preview": false, "summary": "Paranın kökenini deniz kabukları ve takılar gibi 'koleksiyon nesnelerine' dayandırıyor: değer saklayan, taklit edilmesi zor nesneler işbirliğini mümkün kıldı. Bitcoin'in neden değerli olabileceğine dair antropolojik zemin."}, {"id": "szabo-smart-contracts", "title": "Smart Contracts: Building Blocks for Digital Markets", "author": "Nick Szabo", "date": "1996", "cat": "Kripto", "type": "makale", "url": "https://www.fon.hum.uva.nl/rob/Courses/InformationInSpeech/CDROM/Literature/LOTwinterschool2006/szabo.best.vwh.net/smart_contracts_2.html", "pdf": false, "preview": false, "summary": "Sözleşme şartlarını koda gömerek aracıya ve güvene olan ihtiyacı azaltmayı öneren yazı; Szabo'nun 1994'te adını koyduğu 'akıllı sözleşme' kavramını ayrıntılandırıyor. Otomatik satış makinesini ilkel bir örnek olarak gösteriyor."}, {"id": "cypherpunk-manifesto", "title": "A Cypherpunk's Manifesto", "author": "Eric Hughes", "date": "1993-03", "cat": "Kripto", "type": "manifesto", "url": "https://www.activism.net/cypherpunk/manifesto.html", "pdf": false, "preview": false, "summary": "Açık bir toplumda mahremiyetin gizlilikten farklı olduğunu ve onu devletlerin ya da şirketlerin değil, kriptografi yazan insanların koruyacağını savunuyor. 'Cypherpunk'lar kod yazar.'"}, {"id": "vitalik-my-techno-optimism", "title": "My techno-optimism", "author": "Vitalik Buterin", "date": "2023-11", "cat": "Dünya görüşü", "type": "deneme", "url": "https://vitalik.eth.limo/general/2023/11/27/techno_optimism.html", "pdf": false, "preview": false, "summary": "Teknolojinin genel olarak iyi olduğunu kabul edip hangi teknolojiyi geliştirdiğimizin önemli olduğunu söylüyor; savunmayı, merkeziyetsizliği ve demokrasiyi güçlendiren 'd/acc' yaklaşımını öneriyor."}, {"id": "vinge-technological-singularity", "title": "The Coming Technological Singularity", "author": "Vernor Vinge", "date": "1993", "cat": "Yapay zekâ", "type": "deneme", "url": "https://edoras.sdsu.edu/~vinge/misc/singularity.html", "pdf": false, "preview": false, "summary": "İnsanüstü zekânın yaratılmasıyla insanlık tarihinin öngörülemez bir eşiğe, 'tekilliğe' ulaşacağını savunan yazı. Vinge bunun 2005'ten önce ya da 2030'dan sonra olmasına şaşıracağını söylüyor."}, {"id": "unreasonable-effectiveness-of-data", "title": "The Unreasonable Effectiveness of Data", "author": "Alon Halevy, Peter Norvig, Fernando Pereira", "date": "2009", "cat": "Yapay zekâ", "type": "makale", "url": "https://static.googleusercontent.com/media/research.google.com/en//pubs/archive/35179.pdf", "pdf": true, "preview": true, "summary": "Karmaşık zarif modeller yerine devasa veriye dayalı basit modellerin çoğu zaman kazandığını savunuyor. Büyük dil modelleri çağının erken bir habercisi."}, {"id": "wigner-unreasonable-effectiveness", "title": "The Unreasonable Effectiveness of Mathematics in the Natural Sciences", "author": "Eugene Wigner", "date": "1960", "cat": "Dünya görüşü", "type": "makale", "url": "https://webhomes.maths.ed.ac.uk/~v1ranick/papers/wigner.pdf", "pdf": true, "preview": true, "summary": "Soyut düşünceyle icat edilen matematiğin fiziksel dünyayı neden bu kadar isabetli tarif ettiğini soruyor ve bunun bir mucize gibi göründüğünü söylüyor."}, {"id": "dartmouth-ai-proposal", "title": "A Proposal for the Dartmouth Summer Research Project on Artificial Intelligence", "author": "John McCarthy, Marvin Minsky, Nathaniel Rochester, Claude Shannon", "date": "1955-08", "cat": "Yapay zekâ", "type": "öneri", "url": "http://jmc.stanford.edu/articles/dartmouth/dartmouth.pdf", "pdf": true, "preview": false, "summary": "'Yapay zekâ' teriminin ilk kez kullanıldığı belge: öğrenmenin ve zekânın her yönünün bir makinenin taklit edebileceği kadar kesin tarif edilebileceğini öne sürüyor."}, {"id": "domingos-useful-things-ml", "title": "A Few Useful Things to Know about Machine Learning", "author": "Pedro Domingos", "date": "2012-10", "cat": "Yapay zekâ", "type": "makale", "url": "https://homes.cs.washington.edu/~pedrod/papers/cacm12.pdf", "pdf": true, "preview": true, "summary": "Ders kitaplarında yazmayan makine öğrenmesi 'halk bilgisini' 12 derste topluyor: genelleme her şeydir, daha fazla veri akıllı algoritmayı yener, korelasyon nedensellik değildir."}, {"id": "hidden-technical-debt-ml", "title": "Hidden Technical Debt in Machine Learning Systems", "author": "D. Sculley et al. (Google)", "date": "2015-12", "cat": "Yapay zekâ", "type": "makale", "url": "https://papers.nips.cc/paper/2015/file/86df7dcfd896fcaf2674f757a2463eba-Paper.pdf", "pdf": true, "preview": false, "summary": "Gerçek bir makine öğrenmesi sisteminde modelin kodun küçük bir parçası olduğunu, asıl maliyetin veri bağımlılıkları ve tutkal koddan geldiğini gösteriyor. Böyle bir sistemi hızla kurmanın kolay, ayakta tutmanın pahalı olduğunu anlatıyor."}, {"id": "concrete-problems-ai-safety", "title": "Concrete Problems in AI Safety", "author": "Dario Amodei, Chris Olah, Jacob Steinhardt, Paul Christiano, John Schulman, Dan Mané", "date": "2016-06", "cat": "Yapay zekâ", "type": "makale", "url": "https://arxiv.org/pdf/1606.06565", "pdf": true, "preview": true, "summary": "Yapay zekâ güvenliğini spekülasyondan çıkarıp beş somut araştırma problemine indiriyor: yan etkiler, ödül hilesi, ölçeklenebilir denetim, güvenli keşif ve dağılım kayması."}, {"id": "what-failure-looks-like", "title": "What failure looks like", "author": "Paul Christiano", "date": "2019-03", "cat": "Yapay zekâ", "type": "deneme", "url": "https://www.lesswrong.com/posts/HBxe6wdjxK239zajf/what-failure-looks-like", "pdf": false, "preview": false, "summary": "Yapay zekâ felaketinin film senaryosundaki gibi ani bir isyanla değil; ölçülebilir ama yanlış hedeflerin optimize edilmesi ve giderek nüfuz peşine düşen sistemler yüzünden kontrolün adım adım kaybedilmesiyle gelebileceğini anlatıyor."}, {"id": "karpathy-rnn-effectiveness", "title": "The Unreasonable Effectiveness of Recurrent Neural Networks", "author": "Andrej Karpathy", "date": "2015-05", "cat": "Yapay zekâ", "type": "deneme", "url": "https://karpathy.github.io/2015/05/21/rnn-effectiveness/", "pdf": false, "preview": false, "summary": "Karakter karakter metin üreten basit bir ağın Shakespeare'den Linux koduna kadar her şeyi taklit edebildiğini gösteriyor. Dil modellerinin gücünü erken fark ettiren yazı."}, {"id": "bostrom-vulnerable-world", "title": "The Vulnerable World Hypothesis", "author": "Nick Bostrom", "date": "2019", "cat": "Dünya görüşü", "type": "makale", "url": "https://nickbostrom.com/papers/vulnerable.pdf", "pdf": true, "preview": true, "summary": "Teknolojik keşifler torbasından bir gün medeniyeti varsayılan olarak yok eden bir 'siyah top' çekebileceğimizi öne sürüyor ve bunun önlenmesi için gereken bedelleri tartışıyor."}, {"id": "bostrom-simulation-argument", "title": "Are You Living in a Computer Simulation?", "author": "Nick Bostrom", "date": "2003", "cat": "Dünya görüşü", "type": "makale", "url": "https://simulation-argument.com/simulation.pdf", "pdf": true, "preview": true, "summary": "Üç seçenekten en az birinin doğru olması gerektiğini savunuyor: medeniyetlerin neredeyse hepsi olgunlaşmadan yok oluyor, olgunlaşanlar neredeyse hiç simülasyon çalıştırmıyor ya da biz büyük olasılıkla bir simülasyondayız."}, {"id": "bostrom-astronomical-waste", "title": "Astronomical Waste: The Opportunity Cost of Delayed Technological Development", "author": "Nick Bostrom", "date": "2003", "cat": "Dünya görüşü", "type": "makale", "url": "https://nickbostrom.com/papers/astronomical-waste/", "pdf": false, "preview": false, "summary": "Teknolojik ilerlemeyi geciktirmenin kaybettirdiği potansiyel yaşamların devasa olduğunu, ama varoluşsal riski azaltmanın bundan bile daha önemli olduğunu savunuyor. Uzun vadecilik düşüncesinin temel taşlarından."}, {"id": "keynes-economic-possibilities", "title": "Economic Possibilities for our Grandchildren", "author": "John Maynard Keynes", "date": "1930", "cat": "Makro ve yatırım", "type": "deneme", "url": "http://www.econ.yale.edu/smith/econ116a/keynes1.pdf", "pdf": true, "preview": false, "summary": "Büyük Buhran'ın ortasında yüz yıl sonra ekonomik sorunun büyük ölçüde çözüleceğini ve insanların haftada 15 saat çalışacağını öngörüyor. Asıl sorunun boş zamanı nasıl dolduracağımız olacağını söylüyor."}, {"id": "minsky-financial-instability", "title": "The Financial Instability Hypothesis", "author": "Hyman P. Minsky", "date": "1992-05", "cat": "Makro ve yatırım", "type": "makale", "url": "https://www.levyinstitute.org/pubs/wp74.pdf", "pdf": true, "preview": false, "summary": "İstikrarın istikrarsızlığı doğurduğunu savunuyor: sakin dönemlerde borçlanma giderek riskli hale gelir ve sistem kendi içinden krize sürüklenir. 2008'den sonra 'Minsky anı' kavramıyla yeniden keşfedildi."}, {"id": "naval-how-to-get-rich", "title": "How to Get Rich (without getting lucky)", "author": "Naval Ravikant", "date": "2018-05", "cat": "Girişim ve VC", "type": "deneme", "url": "https://nav.al/rich", "pdf": false, "preview": false, "summary": "Zenginliği maaşla değil sahiplikle tarif ediyor: kendine özgü bilgini ve sorumluluk almayı, kod ve medya gibi izin gerektirmeyen kaldıraçlarla birleştir. Uzun vadeli oyunları uzun vadeli insanlarla oyna."}, {"id": "gervais-principle", "title": "The Gervais Principle, Or The Office According to “The Office”", "author": "Venkatesh Rao", "date": "2009-10", "cat": "Dünya görüşü", "type": "deneme", "url": "https://ribbonfarm.com/2009/10/07/the-gervais-principle-or-the-office-according-to-the-office/", "pdf": false, "preview": false, "summary": "Organizasyonları sosyopatlar, kaybedenler ve saflar olarak üçe ayıran karanlık ama keskin bir şirket teorisi. Kimin neden terfi ettiğini bambaşka bir gözle görmeni sağlıyor."}];
